INSERT OR IGNORE INTO academy_knowledge (id, kind, category, title_pl, title_en, content_pl, content_en, tags, source_ref) VALUES
('fault:FAULT-01','fault','Zasilanie','Komputer nie włącza się','Computer will not power on','symptom: Brak reakcji, pojedyncze mignięcie diody lub cykliczne próby startu. focus: Ustal, czy brak jest zasilania wejściowego, czuwania, reakcji EC czy dopiero POST. causes: Brak zasilania w gniazdku lub przewodzie; niezgodny/uszkodzony adapter; uszkodzone DC-IN; bezpiecznik wejściowy; MOSFET lub kontroler ładowania; brak napięć czuwania; EC/KBC nie rozpoczyna sekwencji; zwarcie na linii zasilania. checks: 1) Sprawdź gniazdko innym urządzeniem. 2) Obejrzyj przewód, wtyk i gniazdo bez poruszania nadpalonym złączem. 3) Potwierdź napięcie, moc, polaryzację i identyfikację oryginalnego adaptera. 4) Odłącz akcesoria USB i stację dokującą. 5) Zapisz reakcję LED i przycisku Power. steps: 1) Potwierdź model, dokładną rewizję płyty i zasilacz. 2) Obejrzyj płytę pod kątem korozji, pęknięcia gniazda, nadpaleń i śladów cieczy. 3) Ustal, czy objaw to całkowity brak reakcji, krótkie mignięcie czy pętla startu. 4) Technik identyfikuje DC-IN, bezpiecznik, MOSFET-y, charger i linie standby na schemacie/BoardView. 5) Dopiero potem wykonuje pomiary zgodne z dokumentacją, z kontrolowanymi warunkami. tests: Przed pomiarem potwierdź punkt GND, zakres miernika i stan sond. Rezystancję/ciągłość sprawdzaj wyłącznie po odłączeniu wszystkich źródeł zasilania i rozładowaniu według procedury. Napięć 3V/5V/VIN nie traktuj jako uniwersalnego pinoutu — porównuj z konkretną płytą. repair: Napraw lub wymień wyłącznie element potwierdzony pomiarami i dokumentacją: przewód/adapter, gniazdo, bezpiecznik, element toru wejściowego lub kontroler. Po wymianie usuń przyczynę przeciążenia; nigdy nie zwieraj bezpiecznika. verify: Wykonaj zimny start, kilka kontrolowanych uruchomień, sprawdź stabilność zasilania, ładowanie (jeśli występuje), POST, obraz i brak nadmiernego nagrzewania. Zapisz użyty adapter i wyniki. stop: Przerwij przy dymie, zapachu spalenizny, iskrzeniu, gorącym złączu, cieczy, spuchniętej baterii lub nieznanym zwarciu. Nie otwieraj zasilacza sieciowego.','symptomEn: No response, a brief LED flash or repeated startup attempts. focusEn: Separate missing input power, standby power, EC response and POST failure. causesEn: Wall outlet or cable failure; incorrect/faulty adapter; damaged DC-in; input fuse; MOSFET or charger controller; missing standby rails; EC/KBC does not start the sequence; shorted power rail. checksEn: 1) Verify the outlet with another device. 2) Inspect cable, plug and socket without moving a burnt connector. 3) Confirm the original adapter voltage, wattage, polarity and identification. 4) Disconnect USB accessories and dock. 5) Record LED and power-button response. stepsEn: 1) Confirm model, exact board revision and adapter. 2) Inspect for corrosion, cracked jack, burns and liquid traces. 3) Classify the symptom: no response, brief flash or boot loop. 4) A technician identifies DC-in, fuse, MOSFETs, charger and standby rails in the schematic/BoardView. 5) Only then perform model-documented measurements under controlled conditions. testsEn: Before measuring, confirm GND, meter range and probe condition. Measure resistance/continuity only after disconnecting every power source and following the discharge procedure. Do not treat 3V/5V/VIN as a universal pinout; compare with the exact board. repairEn: Repair or replace only a component confirmed by measurements and documentation: cable/adapter, jack, fuse, input-stage component or controller. Remove the cause of overload; never bridge a fuse. verifyEn: Perform a cold start and several controlled power-ons; verify stable power, charging if applicable, POST, display and absence of abnormal heating. Record the adapter and results. stopEn: Stop for smoke, burning smell, arcing, hot connector, liquid, swollen battery or an unidentified short. Never open a mains PSU.','',''),
('fault:FAULT-02','fault','Płyta główna','Błąd pamięci RAM lub brak POST','RAM error or no POST','symptom: Brak obrazu i zatrzymanie na kontrolce DRAM, sygnały dźwiękowe albo niestabilny start. focus: Nie utożsamiaj braku obrazu z uszkodzeniem RAM; zapisz kod płyty i konfigurację pamięci. causes: Niekompatybilny moduł DDR; źle osadzony DIMM/SODIMM; zabrudzone lub uszkodzone styki; uszkodzony slot; nieprawidłowe ustawienia pamięci/UEFI; problem kontrolera pamięci w CPU lub płycie; nieaktualna/niezgodna wersja firmware. checks: 1) Zapisz sekwencję diod/beep i kod POST. 2) Sprawdź typ DDR, pojemność i specyfikację płyty. 3) Odłącz zasilanie przed wyjmowaniem RAM. 4) Porównaj moduły pojedynczo i sloty zgodnie z instrukcją. 5) Po zmianach pozwól na ewentualny trening pamięci. steps: 1) Przywróć konfigurację minimalną zgodną z dokumentacją. 2) Testuj pojedynczy, znany sprawny moduł w zalecanym slocie. 3) Zapisuj wynik każdej kombinacji moduł/slot. 4) Wyklucz profil XMP/EXPO i niestandardowe taktowanie, wracając do ustawień bezpiecznych. 5) Jeśli objaw pozostaje, technik analizuje zasilanie RAM, linie sygnałowe i kontroler pamięci. tests: Test pamięci uruchamiaj dopiero po ustabilizowaniu konfiguracji. Kod beep jest zależny od BIOS/producenta — interpretuj go z instrukcji danego modelu. Nie mierz linii sygnałowych bez schematu i właściwego sprzętu. repair: Wymień moduł tylko po potwierdzeniu usterki w powtarzalnym teście. Uszkodzony slot lub ścieżka wymaga naprawy płyty; aktualizację BIOS wykonuj wyłącznie, gdy dokumentacja producenta wskazuje taki przypadek i zasilanie jest stabilne. verify: Wykonaj pełny test pamięci, kilka zimnych startów, sprawdź wykrytą pojemność, kanały i stabilność pod normalnym obciążeniem. stop: Przerwij, gdy pojawia się zapach spalenizny, nadmierne nagrzanie modułu/slotu lub uszkodzenie mechaniczne. Nie wkładaj i nie wyjmuj pamięci przy podłączonym zasilaniu.','symptomEn: No display, DRAM indicator, beep pattern or unstable startup. focusEn: Do not equate no display with bad RAM; record board code and memory configuration. causesEn: Incompatible DDR module; poorly seated DIMM/SODIMM; dirty or damaged contacts; faulty slot; incorrect memory/UEFI settings; CPU memory-controller or motherboard fault; firmware compatibility issue. checksEn: 1) Record LED/beep sequence and POST code. 2) Check DDR type, capacity and board specification. 3) Remove power before reseating RAM. 4) Compare modules individually and slots per manual. 5) Allow memory training after configuration changes. stepsEn: 1) Return to a documented minimal configuration. 2) Test one known-good module in the recommended slot. 3) Record every module/slot combination. 4) Rule out XMP/EXPO and custom timings by returning to safe defaults. 5) If the issue remains, a technician checks RAM power, signal lines and memory controller. testsEn: Run memory tests only after the configuration is stable. Beep codes depend on BIOS/vendor; interpret them using the exact model manual. Do not probe signal lines without a schematic and proper equipment. repairEn: Replace a module only after repeatable confirmation. A faulty slot or trace requires board repair; update BIOS only when vendor documentation supports it and power is stable. verifyEn: Run a full memory test and several cold starts; confirm detected capacity, channels and stability under normal load. stopEn: Stop if there is a burning smell, abnormal module/slot heating or mechanical damage. Never insert or remove memory while powered.','',''),
('fault:FAULT-03','fault','Dyski i dane','Dysk znika lub działa wolno','Drive disappears or runs slowly','symptom: Zawieszanie przy odczycie, znikanie nośnika, błędy plików lub długi start. focus: Priorytetem jest kopia danych; najpierw oceń, czy nośnik odpowiada i czy objawy są powtarzalne. causes: Zużycie komórek NAND lub problemy kontrolera; błędy firmware; uszkodzony przewód/gniazdo; niekompatybilny interfejs SATA/NVMe; przegrzewanie; błędy systemu plików; zasilanie nośnika. checks: 1) Jeśli dane są ważne, ogranicz testy i zapisy. 2) Zapisz model nośnika i objawy. 3) Sprawdź, czy nośnik jest wykrywany w UEFI i systemie. 4) Zwróć uwagę na odgłosy mechaniczne HDD. 5) Przy stabilnym nośniku wykonaj kopię najważniejszych danych przed testami. steps: 1) Nie uruchamiaj wielokrotnie klikającego HDD. 2) Sprawdź kabel, port i osadzenie nośnika przy odłączonym zasilaniu. 3) Odczytaj SMART narzędziem producenta lub zaufanym narzędziem, nie traktując jednego parametru jako wyroku. 4) Rozróżnij problemy interfejsu, temperatury, firmware i powierzchni. 5) Przy błędach odczytu wykonaj obraz nośnika na inny sprawny dysk, jeśli stan na to pozwala. tests: SMART to wskaźnik, nie gwarancja sprawności. Testy powierzchniowe, benchmark i CHKDSK mogą pogorszyć sytuację niestabilnego nośnika. Przy niezastąpionych danych najpierw konsultacja z odzyskiem danych. repair: Po bezpiecznej kopii: wymień potwierdzony przewód/adapter, popraw montaż lub wymień nośnik. Firmware aktualizuj tylko według instrukcji producenta i przy stabilnym zasilaniu. Nie formatuj, jeśli dane nie są zabezpieczone. verify: Sprawdź ponowne wykrywanie po zimnym starcie, SMART, temperaturę, transfer dużego pliku oraz odczyt kopii. Zweryfikuj kopię przez otwarcie wybranych plików. stop: Przerwij przy klikaniu/stukaniu HDD, zapachu spalenizny, nadmiernym nagrzaniu, znikaniu nośnika podczas odczytu lub danych o dużej wartości.','symptomEn: Read freezes, disappearing drive, file errors or slow boot. focusEn: Data preservation comes first; determine whether the drive responds and whether symptoms repeat. causesEn: NAND wear or controller issues; firmware errors; damaged cable/connector; SATA/NVMe incompatibility; overheating; filesystem errors; drive power problems. checksEn: 1) If data matters, minimize tests and writes. 2) Record drive model and symptoms. 3) Check detection in UEFI and OS. 4) Listen for mechanical HDD noises. 5) For a stable drive, copy critical data before testing. stepsEn: 1) Do not repeatedly power a clicking HDD. 2) Inspect cable, port and seating with power disconnected. 3) Read SMART using vendor or trusted tools; no single field is a complete verdict. 4) Separate interface, thermal, firmware and media faults. 5) For read errors, image the drive to another healthy disk if its condition permits. testsEn: SMART is an indicator, not a guarantee. Surface tests, benchmarks and CHKDSK can worsen an unstable drive. For irreplaceable data, consult a recovery specialist first. repairEn: After a safe backup: replace a confirmed cable/adapter, reseat or replace the drive. Update firmware only per vendor instructions and with stable power. Do not format before data is secured. verifyEn: Check detection after cold boot, SMART, temperature, large-file transfer and backup readability. Verify the backup by opening sample files. stopEn: Stop for HDD clicking/knocking, burning smell, overheating, drive disappearing during reads or high-value data.','',''),
('fault:FAULT-04','fault','Obraz i matryca','Komputer działa, ale ekran jest czarny','Computer runs but screen is black','symptom: Wentylatory lub diody pracują, ale ekran pozostaje czarny; brak obrazu na starcie albo po logowaniu. focus: Oddziel brak POST, brak podświetlenia, brak sygnału i problem sterownika. causes: Jasność/tryb wyświetlania; uszkodzony panel; taśma eDP/LVDS; brak podświetlenia; złącze lub bezpiecznik podświetlenia; GPU/ścieżka obrazu; sterownik; monitor lub kabel. checks: 1) Zwiększ jasność i wyłącz tryb oszczędzania. 2) Sprawdź, czy widać logo/UEFI. 3) Porównaj obraz na zewnętrznym ekranie. 4) Sprawdź wejście monitora i kabel. 5) Nie ruszaj pokrywą, jeżeli obraz reaguje na jej położenie. steps: 1) Ustal, czy problem występuje już w UEFI, czy dopiero po sterowniku. 2) Zapisz wynik testu zewnętrznego monitora. 3) Technik sprawdza złącze panelu, osadzenie i zgodność przewodu po odłączeniu baterii. 4) Schemat identyfikuje linie zasilania panelu/podświetlenia oraz zabezpieczenia. 5) Weryfikuj panel i przewód na modelu zgodnym, nie na podstawie samego kształtu wtyku. tests: Nie podawaj napięć podświetlenia ani pinów eDP uniwersalnie. Pomiar na złączu panelu jest zadaniem technika: niewłaściwa sonda może spowodować zwarcie i uszkodzić panel lub płytę. repair: Najpierw przywróć właściwe ustawienia/sterownik. Części wymieniaj dopiero po potwierdzeniu: kabel, panel, złącze lub element toru podświetlenia. Napraw mocowań i zawiasów nie odkładaj, jeśli przewód jest naprężony. verify: Sprawdź obraz w UEFI i systemie, kilka poziomów jasności, ruch pokrywy w normalnym zakresie, monitor zewnętrzny oraz brak migotania po wybudzeniu. stop: Przerwij przy pękniętej matrycy, odsłoniętym przewodzie, iskrzeniu, nadpalonym złączu lub konieczności pomiaru bez schematu.','symptomEn: Fans or LEDs run but the screen stays black, at startup or after sign-in. focusEn: Separate no-POST, backlight failure, missing signal and driver problems. causesEn: Brightness/display mode; faulty panel; eDP/LVDS cable; backlight failure; connector or backlight fuse; GPU/display path; driver; monitor or cable. checksEn: 1) Increase brightness and disable power saving. 2) Check whether logo/UEFI appears. 3) Compare with an external display. 4) Check monitor input and cable. 5) Do not move the lid if image changes with its angle. stepsEn: 1) Determine whether the problem exists in UEFI or only after the driver loads. 2) Record external-monitor results. 3) A technician inspects panel connector, seating and cable compatibility after disconnecting the battery. 4) The schematic identifies panel/backlight power rails and protection. 5) Verify panel and cable compatibility for the exact model, not by connector shape alone. testsEn: Do not assume universal backlight voltages or eDP pins. Panel-connector measurements are technician work; a misplaced probe can short and damage the panel or board. repairEn: First restore correct settings/driver. Replace parts only after confirmation: cable, panel, connector or backlight-stage component. Do not delay hinge/mount repairs if the cable is under tension. verifyEn: Verify image in UEFI and OS, several brightness levels, normal lid movement, external display and no flicker after wake. stopEn: Stop for cracked panel, exposed cable, arcing, burnt connector or any measurement without the exact schematic.','',''),
('fault:FAULT-05','fault','Zasilanie i bateria','Bateria nie ładuje','Battery does not charge','symptom: Poziom baterii nie rośnie, status zmienia się lub ładowanie zatrzymuje się na limicie. focus: Sprawdź zasilacz, limit ładowania, stan baterii i wykrywanie jej przez firmware. causes: Limit ładowania w oprogramowaniu; niezgodny adapter lub kabel USB-C PD; zużyte ogniwa; błędna komunikacja baterii; gniazdo DC-IN; kontroler ładowania; problem z czujnikiem temperatury. checks: 1) Sprawdź, czy ładowanie nie ma ustawionego limitu (np. ochrona baterii). 2) Użyj zasilacza o zgodnych parametrach. 3) Zapisz status baterii i raport kondycji. 4) Obejrzyj obudowę pod kątem wybrzuszeń. 5) Sprawdź, czy problem występuje po pełnym wyłączeniu i ponownym starcie. steps: 1) Potwierdź model baterii i adaptera. 2) Porównaj status ładowania w systemie i UEFI, jeśli dostępny. 3) Technik ocenia gniazdo, linie identyfikacji i układ ładowania na schemacie. 4) Sprawdza komunikację BMS oraz czujnik temperatury zgodnie z dokumentacją. 5) Nie wykonuje się „naprawy” przez mostkowanie baterii lub bezpieczników. tests: Nie rozbieraj pakietu Li-ion/Li-pol i nie mierz ogniw bez odpowiedniego wyposażenia. Każdy pomiar na płycie musi być zgodny z dokumentacją modelu. Spuchniętej baterii nie testuj ani nie ładuj. repair: Usuń przyczynę: konfiguracja limitu, zgodny adapter/kabel, naprawa gniazda lub obwodu ładowania, wymiana baterii na zatwierdzony numer części. Nie stosuj zamiennika bez zgodności napięcia, BMS i mechaniki. verify: Sprawdź wykrywanie baterii, zmianę poziomu w czasie, ładowanie przy wyłączonym i włączonym urządzeniu, temperaturę i komunikaty systemu. stop: Spuchnięcie, przebicie, wyciek, syczenie, zapach chemiczny lub nadmierne grzanie baterii oznaczają STOP. Nie ściskaj, nie przekłuwaj i nie wrzucaj do zwykłych odpadów.','symptomEn: Battery percentage does not rise, status changes or charging stops at a configured threshold. focusEn: Check adapter, charge limit, battery health and firmware detection. causesEn: Charge threshold in software; incompatible adapter or USB-C PD cable; worn cells; battery communication fault; DC-in jack; charger controller; temperature-sensor issue. checksEn: 1) Check whether charging is limited by a battery-protection feature. 2) Use an adapter with matching specifications. 3) Record battery status and health report. 4) Inspect for swelling. 5) Check after a full shutdown and restart. stepsEn: 1) Confirm battery and adapter models. 2) Compare charging status in OS and UEFI if available. 3) A technician checks jack, identification lines and charger circuit against the schematic. 4) Check BMS communication and temperature sensor per documentation. 5) Never “repair” by bridging battery protection or fuses. testsEn: Do not dismantle a Li-ion/Li-pol pack or probe cells without proper equipment. Board measurements must follow exact model documentation. Never test or charge a swollen battery. repairEn: Correct the cause: charge limit setting, compatible adapter/cable, jack or charging-circuit repair, or battery replacement with approved part number. Do not use a substitute without voltage, BMS and mechanical compatibility. verifyEn: Check battery detection, percentage change over time, charging while off/on, temperature and OS messages. stopEn: Swelling, puncture, leakage, hissing, chemical odor or excessive battery heat mean STOP. Do not squeeze, puncture or place in ordinary waste.','',''),
('fault:FAULT-06','fault','Chłodzenie','Przegrzewanie i nieoczekiwane restarty','Overheating and unexpected restarts','symptom: Wysokie temperatury, głośne wentylatory, spadki wydajności lub wyłączenie pod obciążeniem. focus: Nie zaczynaj od testu obciążeniowego; sprawdź wentylację, czujniki i zachowanie w spoczynku. causes: Kurz i zablokowane wloty; zużyty wentylator; nieprawidłowy docisk radiatora; wyschnięty materiał termiczny; błędne termopady; wysoki proces obciążający; ograniczenia zasilania lub czujnik temperatury. checks: 1) Ustaw komputer na twardej, płaskiej powierzchni. 2) Sprawdź wloty i wyloty powietrza. 3) Zapisz temperatury w spoczynku i typowym zadaniu. 4) Sprawdź obciążenie CPU/GPU. 5) Nie uruchamiaj długiego benchmarku, gdy występuje wyłączenie lub zapach spalenizny. steps: 1) Potwierdź model wentylatora i układ chłodzenia. 2) Obejrzyj radiator i kanały powietrzne po bezpiecznym odłączeniu zasilania. 3) Technik ocenia docisk i stan pasty/termopadów oraz ich prawidłową grubość. 4) Sprawdź krzywą PWM i odczyty czujników, porównując z limitem producenta. 5) Testuj krótko i stopniowo, obserwując temperatury i zegary. tests: Odczyty z aplikacji zależą od czujnika i BIOS; nie istnieje jedna temperatura alarmowa dla wszystkich CPU/GPU. Zwróć uwagę na throttling, nagły wzrost i różnicę między rdzeniami. repair: Oczyść kanały i wentylatory bez uszkadzania łopatek; wymień uszkodzony wentylator na dokładny zamiennik; popraw montaż chłodzenia i zastosuj materiał o właściwych parametrach. Nie zastępuj termopadów pastą bez specyfikacji. verify: Powtórz identyczny, krótki test; porównaj temperatury, zegary, hałas i stabilność. Sprawdź wentylator w całym zakresie pracy i temperatury po wybudzeniu. stop: Przerwij przy nagłym wyłączaniu, zapachu, dymie, niesprawnym wentylatorze w urządzeniu o wysokiej temperaturze lub gorącej baterii.','symptomEn: High temperatures, loud fans, performance drops or shutdown under load. focusEn: Do not start with a stress test; inspect airflow, sensors and idle behavior first. causesEn: Dust and blocked vents; worn fan; poor heatsink contact; degraded thermal compound; incorrect thermal pads; high CPU/GPU load; power limits or temperature sensor. checksEn: 1) Place the computer on a hard, flat surface. 2) Inspect air intake/exhaust. 3) Record idle and normal-work temperatures. 4) Check CPU/GPU load. 5) Do not run a long benchmark if shutdown or burning smell occurs. stepsEn: 1) Confirm fan and cooling assembly model. 2) Inspect heatsink and airflow paths after safely disconnecting power. 3) A technician checks mounting pressure and thermal compound/pad condition and exact pad thickness. 4) Check PWM curve and sensors against vendor limits. 5) Test briefly and progressively while watching temperature and clocks. testsEn: Software readings depend on sensor and BIOS; there is no single alarm temperature for all CPUs/GPUs. Watch throttling, rapid rise and core-to-core differences. repairEn: Clean ducts and fans without damaging blades; replace a failed fan with the exact compatible part; correct heatsink mounting and use specified thermal materials. Do not replace pads with paste without specifications. verifyEn: Repeat the same short test; compare temperature, clocks, noise and stability. Check fan operation across its range and temperatures after wake. stopEn: Stop for sudden shutdown, odor, smoke, failed fan under high heat or hot battery.','',''),
('fault:FAULT-07','fault','Sieć','Nie działa Wi-Fi','Wi-Fi does not work','symptom: Brak sieci, znikająca karta, niemożliwe połączenie lub rozłączenia. focus: Porównaj inne urządzenie w tej samej sieci i laptop w innej sieci. causes: Tryb samolotowy lub przełącznik radiowy; router/AP; błędne hasło; sterownik; usługa systemowa; oszczędzanie energii; antena lub karta Wi-Fi; DHCP/DNS/WAN. checks: 1) Sprawdź tryb samolotowy i fizyczny przełącznik. 2) Porównaj telefon w tej samej sieci. 3) Sprawdź laptop w innej sieci. 4) Zapisz komunikat błędu i siłę sygnału. 5) Uruchom ponownie router tylko po zapisaniu jego statusu i upewnieniu się, że nie wykonuje aktualizacji. steps: 1) Ustal, czy problem dotyczy jednej sieci, wszystkich sieci czy samej karty. 2) Sprawdź Menedżer urządzeń i kod urządzenia. 3) Przywróć właściwy sterownik z witryny producenta po zidentyfikowaniu karty. 4) Sprawdź adres IP, bramę i DNS. 5) Jeśli sygnał jest słaby w kilku lokalizacjach, technik sprawdza anteny i przewody. tests: Zapisz wynik ipconfig /all, ping do bramy i rozpoznawanie nazw DNS. Nie wyłączaj zabezpieczeń routera ani zapory jako „testu” na stałe. repair: Popraw ustawienia sieci, hasło, sterownik lub konfigurację routera. Kartę/antenę wymieniaj dopiero po potwierdzeniu sprzętowym i zgodności z platformą. verify: Sprawdź połączenie po restarcie, transfer pliku, roaming, DNS i stabilność przez kilka minut w zwykłym miejscu użytkowania. stop: Przerwij przy uszkodzonym złączu antenowym, śladach cieczy lub konieczności otwarcia zasilacza/routera. Nie resetuj routera do ustawień fabrycznych bez kopii konfiguracji.','symptomEn: No networks, missing adapter, failed connection or repeated drops. focusEn: Compare another device on the same network and the laptop on a different network. causesEn: Airplane mode or radio switch; router/AP; incorrect password; driver; OS service; power saving; antenna or Wi-Fi card; DHCP/DNS/WAN. checksEn: 1) Check airplane mode and physical switch. 2) Compare a phone on the same network. 3) Test the laptop on another network. 4) Record error message and signal strength. 5) Restart the router only after recording its status and confirming it is not updating. stepsEn: 1) Determine whether the problem affects one network, all networks or the adapter itself. 2) Check Device Manager and device code. 3) Install the correct vendor driver after identifying the adapter. 4) Check IP address, gateway and DNS. 5) If signal is weak in multiple locations, a technician inspects antennas and cables. testsEn: Record ipconfig /all, gateway ping and DNS resolution. Do not permanently disable router security or firewall as a “test”. repairEn: Correct network settings, password, driver or router configuration. Replace adapter/antenna only after hardware confirmation and platform compatibility check. verifyEn: Check connection after restart, file transfer, roaming, DNS and stability for several minutes in the normal use location. stopEn: Stop for damaged antenna connector, liquid traces or any need to open a PSU/router. Do not factory-reset a router without configuration backup.','',''),
('fault:FAULT-08','fault','Porty i złącza','Nie działa port USB lub HDMI','USB or HDMI port does not work','symptom: Port nie wykrywa akcesorium, nie przekazuje obrazu lub ma luźne/nadpalone gniazdo. focus: Najpierw wyklucz przewód, akcesorium, wejście monitora i ograniczenia funkcji portu. causes: Uszkodzony kabel/akcesorium; ograniczona funkcja danego portu; zabrudzone lub wygięte styki; zabezpieczenie ESD/TVS; bezpiecznik/polyfuse; kontroler USB/PCH; niewłaściwy adapter lub wersja protokołu. checks: 1) Sprawdź inne akcesorium i znany sprawny kabel. 2) Wypróbuj drugi port. 3) Obejrzyj złącze bez wkładania metalowych przedmiotów. 4) Dla wideo sprawdź wejście i źródło monitora. 5) Dla USB-C potwierdź w specyfikacji obsługę danych, ładowania i obrazu oddzielnie. steps: 1) Zapisz urządzenie, kabel, port i dokładny objaw. 2) Sprawdź wykrywanie w systemie i komunikaty. 3) Technik ogląda styki, mocowanie i ochronę ESD. 4) Schemat wskazuje zasilanie portu, kontroler i linie danych. 5) Nie wykonuj pomiarów na pinach przy niepewnym pinoucie. tests: USB-C/HDMI/USB mają różne pinouty i warianty. Nie zakładaj, że kolory przewodów lub pinout z ogólnej planszy pasują do każdego kabla/gniazda. repair: Wymień uszkodzony kabel/adapter; napraw mechaniczne mocowanie złącza; wymień bezpiecznik lub ochronę dopiero po ustaleniu przyczyny. Uszkodzenia linii sygnałowych i kontrolera wymagają naprawy płyty. verify: Sprawdź kilka cykli podłączania, transfer danych lub obraz, stabilność zasilania oraz brak nagrzewania złącza. stop: Przerwij przy wygiętych pinach, iskrzeniu, nadpaleniu, wodzie lub nagrzewaniu kabla/portu.','symptomEn: Port does not detect a device, output video or has a loose/burnt connector. focusEn: First rule out cable, accessory, monitor input and port feature limitations. causesEn: Faulty cable/accessory; port feature limitation; dirty or bent contacts; ESD/TVS protection; fuse/polyfuse; USB/PCH controller; incompatible adapter or protocol version. checksEn: 1) Test another accessory and known-good cable. 2) Try another port. 3) Inspect the connector without inserting metal objects. 4) For video, check monitor input/source. 5) For USB-C, verify data, charging and video capabilities separately in the specification. stepsEn: 1) Record device, cable, port and exact symptom. 2) Check OS detection and messages. 3) A technician inspects contacts, mounting and ESD protection. 4) The schematic identifies port power, controller and data lines. 5) Never probe pins with an uncertain pinout. testsEn: USB-C/HDMI/USB have different pinouts and variants. Do not assume wire colors or a generic chart match every cable/connector. repairEn: Replace a faulty cable/adapter; repair mechanical connector mounting; replace fuse/protection only after identifying the cause. Signal-line or controller damage requires board repair. verifyEn: Check multiple connect cycles, data transfer or video, stable power and no connector heating. stopEn: Stop for bent pins, arcing, burning, liquid or cable/port heating.','',''),
('fault:FAULT-09','fault','Audio','Brak dźwięku lub mikrofonu','No sound or microphone input','symptom: Nie słychać głośników, słuchawek lub rozmówca nie odbiera głosu. focus: Sprawdź urządzenie wyjściowe/wejściowe, wyciszenie i uprawnienia aplikacji. causes: Złe urządzenie domyślne; wyciszenie; uprawnienia; poziom wejścia; sterownik audio; gniazdo jack; uszkodzony przewód głośnika; kodek audio lub układ na płycie. checks: 1) Sprawdź głośność i wyciszenie. 2) Wybierz prawidłowe wyjście/wejście. 3) Porównaj słuchawki, głośniki i mikrofon zewnętrzny. 4) Sprawdź uprawnienia mikrofonu. 5) Wykonaj próbę w drugiej aplikacji. steps: 1) Oddziel problem całego systemu od jednej aplikacji. 2) Sprawdź Menedżer urządzeń i wersję sterownika. 3) Wyłącz na próbę efekty audio, zapisując stan poprzedni. 4) Technik sprawdza gniazdo, przewody i kodek na schemacie. 5) Porównaj działanie przed i po wznowieniu z uśpienia. tests: Test mikrofonu wykonuj z prawidłowym urządzeniem i poziomem wejścia; sprawdź też fizyczny przełącznik mute w zestawie słuchawkowym. repair: Przywróć właściwe urządzenie, ustawienia lub sterownik. Wymieniaj jack/głośnik/mikrofon lub naprawiaj układ dopiero po porównaniu z urządzeniem zewnętrznym. verify: Zapisz próbkę, odtwórz dźwięk przez każdy tor, sprawdź mikrofon w rozmowie i brak trzasków po restarcie. stop: Przerwij przy zalaniu, zwarciu, nadpalonym jacku lub nietypowym nagrzewaniu.','symptomEn: Speakers or headphones are silent, or the other party cannot hear the microphone. focusEn: Check selected input/output device, mute state and application permissions. causesEn: Wrong default device; mute; permissions; input level; audio driver; jack; damaged speaker cable; audio codec or board circuit. checksEn: 1) Check volume and mute. 2) Select the correct output/input. 3) Compare headphones, speakers and an external microphone. 4) Check microphone permissions. 5) Test in another app. stepsEn: 1) Separate system-wide failure from one app. 2) Check Device Manager and driver version. 3) Temporarily disable audio effects while recording original settings. 4) A technician checks jack, cables and codec using the schematic. 5) Compare operation before and after wake. testsEn: Test the microphone with the correct input and gain; also check the headset’s physical mute switch. repairEn: Restore the correct device, settings or driver. Replace jack/speaker/microphone or repair the codec only after comparison with an external device. verifyEn: Record a sample, play through each output path, test the microphone in a call and confirm no crackle after restart. stopEn: Stop for liquid damage, short circuit, burnt jack or abnormal heating.','',''),
('fault:FAULT-10','fault','Bezpieczeństwo','Zalanie, dym, zapach spalenizny lub spuchnięta bateria','Liquid damage, smoke, burning smell or swollen battery','symptom: Kontakt z cieczą, ślady korozji, dym, nadtopienia, zapach spalenizny albo deformacja obudowy. focus: To przypadek STOP: nie uruchamiaj i nie ładuj urządzenia w celu sprawdzenia, czy działa. causes: Ciecz może powodować zwarcie natychmiast lub korozję rozwijającą się później; zasilanie może przyspieszyć uszkodzenia. Spuchnięta bateria może być niebezpieczna. checks: 1) Nie naciskaj Power. 2) Odłącz ładowarkę z gniazdka, jeśli można to zrobić bez kontaktu z cieczą. 3) Nie ładuj i nie próbuj suszyć gorącym powietrzem. 4) Zabezpiecz sprzęt przed ponownym podłączeniem. 5) Zapisz rodzaj cieczy i czas zdarzenia. steps: 1) Oznacz urządzenie jako zalane/nieuruchamiać. 2) Technik bezpiecznie izoluje zasilanie i ocenia baterię. 3) Dokumentuje obszary korozji, osady i uszkodzone elementy. 4) Demontaż, czyszczenie i pomiary prowadzi według procedury serwisowej; samo wyschnięcie nie usuwa korozji. 5) Ocenia, czy naprawa i odzysk danych są bezpieczne. tests: Nie wykonuj próby startu, testu ładowania ani pomiaru rezystancji przy podłączonym zasilaniu. W przypadku spuchniętej baterii stosuj procedury bezpieczeństwa dla baterii litowych. repair: Naprawa wymaga pełnej oceny korozji, usunięcia zanieczyszczeń właściwą metodą, wymiany uszkodzonych elementów i potwierdzenia izolacji. Odzysk danych może mieć pierwszeństwo przed naprawą. verify: Uruchomienie dopiero po zakończeniu inspekcji i zatwierdzeniu przez technika. Testuj ładowanie, pobór, temperatury, porty i stabilność etapami. stop: Każdy dym, syczenie, puchnięcie, wysoka temperatura, wyciek lub nieznany stan baterii oznacza natychmiastowe przerwanie. Nie transportuj luźnej uszkodzonej baterii bez zabezpieczenia.','symptomEn: Liquid exposure, corrosion, smoke, melted areas, burning odor or case deformation. focusEn: This is a STOP condition: do not power or charge the device to see whether it still works. causesEn: Liquid can cause an immediate short or delayed corrosion; power can accelerate damage. A swollen battery may be hazardous. checksEn: 1) Do not press Power. 2) Disconnect the charger at the wall if it can be done without contact with liquid. 3) Do not charge or use hot air to dry. 4) Prevent reconnection. 5) Record liquid type and exposure time. stepsEn: 1) Label the device as liquid-damaged/do not power. 2) A technician safely isolates power and assesses the battery. 3) Document corrosion, residue and damaged parts. 4) Disassembly, cleaning and measurements follow service procedures; drying alone does not remove corrosion. 5) Assess whether repair and data recovery are safe. testsEn: Do not attempt startup, charging or resistance measurements with power connected. For swollen batteries, follow lithium-battery safety procedures. repairEn: Repair requires full corrosion assessment, appropriate residue removal, replacement of damaged components and insulation verification. Data recovery may take priority over repair. verifyEn: Power on only after inspection is complete and a technician approves. Test charging, current draw, temperature, ports and stability in stages. stopEn: Smoke, hissing, swelling, high temperature, leakage or unknown battery condition requires immediate stop. Do not transport a loose damaged battery without proper containment.','',''),
('fault:FAULT-11','fault','Dyski i dane','Dysk HDD klika lub stuka','HDD clicks or knocks','symptom: Powtarzalne klikanie, stukanie, znikanie dysku lub problemy z odczytem. focus: Ogranicz uruchomienia i nie wykonuj testów powierzchniowych na jedynym egzemplarzu danych. causes: Zużycie komórek NAND lub problemy kontrolera; błędy firmware; uszkodzony przewód/gniazdo; niekompatybilny interfejs SATA/NVMe; przegrzewanie; błędy systemu plików; zasilanie nośnika. checks: 1) Jeśli dane są ważne, ogranicz testy i zapisy. 2) Zapisz model nośnika i objawy. 3) Sprawdź, czy nośnik jest wykrywany w UEFI i systemie. 4) Zwróć uwagę na odgłosy mechaniczne HDD. 5) Przy stabilnym nośniku wykonaj kopię najważniejszych danych przed testami. steps: 1) Nie uruchamiaj wielokrotnie klikającego HDD. 2) Sprawdź kabel, port i osadzenie nośnika przy odłączonym zasilaniu. 3) Odczytaj SMART narzędziem producenta lub zaufanym narzędziem, nie traktując jednego parametru jako wyroku. 4) Rozróżnij problemy interfejsu, temperatury, firmware i powierzchni. 5) Przy błędach odczytu wykonaj obraz nośnika na inny sprawny dysk, jeśli stan na to pozwala. tests: SMART to wskaźnik, nie gwarancja sprawności. Testy powierzchniowe, benchmark i CHKDSK mogą pogorszyć sytuację niestabilnego nośnika. Przy niezastąpionych danych najpierw konsultacja z odzyskiem danych. repair: Po bezpiecznej kopii: wymień potwierdzony przewód/adapter, popraw montaż lub wymień nośnik. Firmware aktualizuj tylko według instrukcji producenta i przy stabilnym zasilaniu. Nie formatuj, jeśli dane nie są zabezpieczone. verify: Sprawdź ponowne wykrywanie po zimnym starcie, SMART, temperaturę, transfer dużego pliku oraz odczyt kopii. Zweryfikuj kopię przez otwarcie wybranych plików. stop: Przerwij przy klikaniu/stukaniu HDD, zapachu spalenizny, nadmiernym nagrzaniu, znikaniu nośnika podczas odczytu lub danych o dużej wartości.','symptomEn: Repeated clicking, knocking, drive disappearance or read problems. focusEn: Limit power cycles and do not run surface tests on the only copy of important data. causesEn: NAND wear or controller issues; firmware errors; damaged cable/connector; SATA/NVMe incompatibility; overheating; filesystem errors; drive power problems. checksEn: 1) If data matters, minimize tests and writes. 2) Record drive model and symptoms. 3) Check detection in UEFI and OS. 4) Listen for mechanical HDD noises. 5) For a stable drive, copy critical data before testing. stepsEn: 1) Do not repeatedly power a clicking HDD. 2) Inspect cable, port and seating with power disconnected. 3) Read SMART using vendor or trusted tools; no single field is a complete verdict. 4) Separate interface, thermal, firmware and media faults. 5) For read errors, image the drive to another healthy disk if its condition permits. testsEn: SMART is an indicator, not a guarantee. Surface tests, benchmarks and CHKDSK can worsen an unstable drive. For irreplaceable data, consult a recovery specialist first. repairEn: After a safe backup: replace a confirmed cable/adapter, reseat or replace the drive. Update firmware only per vendor instructions and with stable power. Do not format before data is secured. verifyEn: Check detection after cold boot, SMART, temperature, large-file transfer and backup readability. Verify the backup by opening sample files. stopEn: Stop for HDD clicking/knocking, burning smell, overheating, drive disappearing during reads or high-value data.','',''),
('fault:FAULT-12','fault','Grafika','Artefakty, pasy lub migotanie grafiki','GPU artifacts, lines or flickering','symptom: Kolorowe bloki, pasy, migotanie lub zniekształcenia obrazu. focus: Sprawdź, czy objaw występuje przed startem systemu oraz na drugim ekranie. causes: Sterownik GPU; przegrzewanie rdzenia lub VRAM; uszkodzona pamięć VRAM; niestabilne zasilanie GPU; problem z magistralą PCIe; uszkodzone połączenie lub sam układ graficzny. Artefakty mogą też pochodzić z kabla, monitora lub aplikacji. checks: 1) Sprawdź, czy artefakty pojawiają się już w UEFI/BIOS. 2) Porównaj obraz na innym przewodzie i monitorze. 3) Zapisz model GPU, sterownik, temperaturę i moment wystąpienia. 4) Sprawdź, czy problem występuje w jednej aplikacji czy wszędzie. 5) Nie rozpoczynaj od długiego testu obciążeniowego. steps: 1) Rozdziel artefakty na wyjściu (kabel/monitor) od problemu renderowania lub sprzętu. 2) Sprawdź logi systemu i wersję sterownika; w razie związku z aktualizacją wykonaj kontrolowany rollback. 3) Zweryfikuj chłodzenie, wentylatory i osadzenie karty po odłączeniu zasilania. 4) Technik sprawdza zasilanie GPU, VRAM i magistralę PCIe według dokumentacji konkretnej karty/płyty. 5) Układów BGA nie podgrzewaj „na próbę”. tests: Porównaj obraz przed uruchomieniem systemu, w trybie awaryjnym i przy sterowniku producenta. Temperatury i napięcia porównuj z limitem producenta konkretnego GPU. Nie ma uniwersalnej temperatury ani punktów pomiarowych dla wszystkich kart. repair: Usuń potwierdzony problem przewodu/monitora lub sterownika. Oczyść układ chłodzenia i wymień materiały termiczne tylko zgodnie z konstrukcją. Naprawy VRAM, VRM i BGA powierz wyspecjalizowanemu serwisowi po diagnozie. verify: Przetestuj kilka wyjść obrazu, rozdzielczości i aplikacji, monitoruj temperatury oraz wykonaj krótki, kontrolowany test stabilności. Zweryfikuj brak artefaktów po zimnym starcie i restarcie. stop: Przerwij przy zapachu spalenizny, dymie, zwarciu, skrajnie wysokiej temperaturze, uszkodzonym złączu zasilania lub artefaktach nasilających się pod obciążeniem.','symptomEn: Colored blocks, lines, flickering or image corruption. focusEn: Check whether the fault appears before OS startup and on a second display. causesEn: GPU driver; overheating of the core or VRAM; faulty VRAM; unstable GPU power; PCIe bus issue; damaged connection or GPU silicon. Artifacts can also originate from the cable, monitor or application. checksEn: 1) Check whether artifacts appear in UEFI/BIOS. 2) Compare with another cable and monitor. 3) Record GPU model, driver, temperature and when the issue starts. 4) Determine whether it occurs in one app or everywhere. 5) Do not begin with a prolonged stress test. stepsEn: 1) Separate output-path artifacts (cable/monitor) from rendering or hardware faults. 2) Check system logs and driver version; roll back only when linked to an update. 3) Verify cooling, fans and card seating with power disconnected. 4) A technician checks GPU power, VRAM and PCIe per the exact card/board documentation. 5) Never reflow BGA as a trial fix. testsEn: Compare output before OS boot, in safe mode and with the vendor driver. Compare temperatures and rails against the exact GPU specification. There is no universal temperature or test point for all cards. repairEn: Correct a confirmed cable/monitor or driver issue. Clean cooling and replace thermal materials only according to the design. VRAM, VRM and BGA repairs require a specialist after diagnosis. verifyEn: Test several display outputs, resolutions and apps, monitor temperatures and run a short controlled stability test. Verify no artifacts after cold boot and restart. stopEn: Stop for burning smell, smoke, short circuit, extreme temperature, damaged power connector or artifacts that worsen under load.','',''),
('fault:FAULT-13','fault','Matryca i taśma','Ekran miga przy poruszaniu pokrywą','Screen flickers when moving the lid','symptom: Obraz przerywa podczas zmiany kąta ekranu lub pojawiają się pionowe pasy. focus: Nie wyginaj dalej pokrywy; ryzyko uszkodzenia przewodu, panelu i mocowań. causes: Jasność/tryb wyświetlania; uszkodzony panel; taśma eDP/LVDS; brak podświetlenia; złącze lub bezpiecznik podświetlenia; GPU/ścieżka obrazu; sterownik; monitor lub kabel. checks: 1) Zwiększ jasność i wyłącz tryb oszczędzania. 2) Sprawdź, czy widać logo/UEFI. 3) Porównaj obraz na zewnętrznym ekranie. 4) Sprawdź wejście monitora i kabel. 5) Nie ruszaj pokrywą, jeżeli obraz reaguje na jej położenie. steps: 1) Ustal, czy problem występuje już w UEFI, czy dopiero po sterowniku. 2) Zapisz wynik testu zewnętrznego monitora. 3) Technik sprawdza złącze panelu, osadzenie i zgodność przewodu po odłączeniu baterii. 4) Schemat identyfikuje linie zasilania panelu/podświetlenia oraz zabezpieczenia. 5) Weryfikuj panel i przewód na modelu zgodnym, nie na podstawie samego kształtu wtyku. tests: Nie podawaj napięć podświetlenia ani pinów eDP uniwersalnie. Pomiar na złączu panelu jest zadaniem technika: niewłaściwa sonda może spowodować zwarcie i uszkodzić panel lub płytę. repair: Najpierw przywróć właściwe ustawienia/sterownik. Części wymieniaj dopiero po potwierdzeniu: kabel, panel, złącze lub element toru podświetlenia. Napraw mocowań i zawiasów nie odkładaj, jeśli przewód jest naprężony. verify: Sprawdź obraz w UEFI i systemie, kilka poziomów jasności, ruch pokrywy w normalnym zakresie, monitor zewnętrzny oraz brak migotania po wybudzeniu. stop: Przerwij przy pękniętej matrycy, odsłoniętym przewodzie, iskrzeniu, nadpalonym złączu lub konieczności pomiaru bez schematu.','symptomEn: Image cuts out as screen angle changes or vertical lines appear. focusEn: Do not keep flexing the lid; the cable, panel and mounts may be damaged. causesEn: Brightness/display mode; faulty panel; eDP/LVDS cable; backlight failure; connector or backlight fuse; GPU/display path; driver; monitor or cable. checksEn: 1) Increase brightness and disable power saving. 2) Check whether logo/UEFI appears. 3) Compare with an external display. 4) Check monitor input and cable. 5) Do not move the lid if image changes with its angle. stepsEn: 1) Determine whether the problem exists in UEFI or only after the driver loads. 2) Record external-monitor results. 3) A technician inspects panel connector, seating and cable compatibility after disconnecting the battery. 4) The schematic identifies panel/backlight power rails and protection. 5) Verify panel and cable compatibility for the exact model, not by connector shape alone. testsEn: Do not assume universal backlight voltages or eDP pins. Panel-connector measurements are technician work; a misplaced probe can short and damage the panel or board. repairEn: First restore correct settings/driver. Replace parts only after confirmation: cable, panel, connector or backlight-stage component. Do not delay hinge/mount repairs if the cable is under tension. verifyEn: Verify image in UEFI and OS, several brightness levels, normal lid movement, external display and no flicker after wake. stopEn: Stop for cracked panel, exposed cable, arcing, burnt connector or any measurement without the exact schematic.','',''),
('fault:FAULT-14','fault','Chłodzenie','Wentylator hałasuje lub ociera','Fan is noisy or rubbing','symptom: Ter kotanie, szum, wibracje, zmienna prędkość lub komunikat fan error. focus: Oceń temperaturę i hałas przy małym obciążeniu; nie zatrzymuj łopatek ręką. causes: Kurz i zablokowane wloty; zużyty wentylator; nieprawidłowy docisk radiatora; wyschnięty materiał termiczny; błędne termopady; wysoki proces obciążający; ograniczenia zasilania lub czujnik temperatury. checks: 1) Ustaw komputer na twardej, płaskiej powierzchni. 2) Sprawdź wloty i wyloty powietrza. 3) Zapisz temperatury w spoczynku i typowym zadaniu. 4) Sprawdź obciążenie CPU/GPU. 5) Nie uruchamiaj długiego benchmarku, gdy występuje wyłączenie lub zapach spalenizny. steps: 1) Potwierdź model wentylatora i układ chłodzenia. 2) Obejrzyj radiator i kanały powietrzne po bezpiecznym odłączeniu zasilania. 3) Technik ocenia docisk i stan pasty/termopadów oraz ich prawidłową grubość. 4) Sprawdź krzywą PWM i odczyty czujników, porównując z limitem producenta. 5) Testuj krótko i stopniowo, obserwując temperatury i zegary. tests: Odczyty z aplikacji zależą od czujnika i BIOS; nie istnieje jedna temperatura alarmowa dla wszystkich CPU/GPU. Zwróć uwagę na throttling, nagły wzrost i różnicę między rdzeniami. repair: Oczyść kanały i wentylatory bez uszkadzania łopatek; wymień uszkodzony wentylator na dokładny zamiennik; popraw montaż chłodzenia i zastosuj materiał o właściwych parametrach. Nie zastępuj termopadów pastą bez specyfikacji. verify: Powtórz identyczny, krótki test; porównaj temperatury, zegary, hałas i stabilność. Sprawdź wentylator w całym zakresie pracy i temperatury po wybudzeniu. stop: Przerwij przy nagłym wyłączaniu, zapachu, dymie, niesprawnym wentylatorze w urządzeniu o wysokiej temperaturze lub gorącej baterii.','symptomEn: Rattle, grinding, vibration, changing speed or fan error. focusEn: Check temperature and noise at low load; never stop blades with a finger. causesEn: Dust and blocked vents; worn fan; poor heatsink contact; degraded thermal compound; incorrect thermal pads; high CPU/GPU load; power limits or temperature sensor. checksEn: 1) Place the computer on a hard, flat surface. 2) Inspect air intake/exhaust. 3) Record idle and normal-work temperatures. 4) Check CPU/GPU load. 5) Do not run a long benchmark if shutdown or burning smell occurs. stepsEn: 1) Confirm fan and cooling assembly model. 2) Inspect heatsink and airflow paths after safely disconnecting power. 3) A technician checks mounting pressure and thermal compound/pad condition and exact pad thickness. 4) Check PWM curve and sensors against vendor limits. 5) Test briefly and progressively while watching temperature and clocks. testsEn: Software readings depend on sensor and BIOS; there is no single alarm temperature for all CPUs/GPUs. Watch throttling, rapid rise and core-to-core differences. repairEn: Clean ducts and fans without damaging blades; replace a failed fan with the exact compatible part; correct heatsink mounting and use specified thermal materials. Do not replace pads with paste without specifications. verifyEn: Repeat the same short test; compare temperature, clocks, noise and stability. Check fan operation across its range and temperatures after wake. stopEn: Stop for sudden shutdown, odor, smoke, failed fan under high heat or hot battery.','',''),
('fault:FAULT-15','fault','Klawiatura','Nie działa jeden lub kilka klawiszy','One or more keyboard keys do not work','symptom: Pojedyncze klawisze, rzędy lub cała klawiatura nie reagują albo wpisują inne znaki. focus: Porównaj klawiaturę ekranową/zewnętrzną i sprawdź układ języka oraz Fn/NumLock. causes: Wyłączony touchpad/klawiatura skrótem; układ języka; sterownik; zabrudzona klawiatura; uszkodzona membrana/matryca klawiszy; taśma; zalanie; problem EC/KBC. checks: 1) Sprawdź układ języka, NumLock/Fn i skrót wyłączenia. 2) Porównaj z klawiaturą zewnętrzną. 3) Sprawdź, czy usterka występuje przed uruchomieniem systemu. 4) Zapisz, czy nie działa jeden klawisz, rząd czy całość. 5) Po zalaniu nie włączaj urządzenia. steps: 1) Wyklucz ustawienia i aplikację. 2) Sprawdź urządzenie w UEFI/diagnostyce producenta, jeśli dostępna. 3) Technik odłącza baterię i sprawdza taśmę, blokadę ZIF, styki i oznaczenie części. 4) Ocenia ślady cieczy i obwód EC/KBC, jeśli problem dotyczy wielu klawiszy. 5) Nie wkładaj taśmy na siłę i nie podnoś blokady metalowym ostrzem. tests: Nie ma uniwersalnego testu rezystancji matrycy klawiatury. Wymagane są pinout i dokumentacja konkretnego modelu. repair: Popraw ustawienia/sterownik; wyczyść lub wymień klawiaturę/touchpad zgodnie z procedurą i numerem części. Napraw taśmy/złącza lub EC/KBC powierz specjaliście. verify: Przetestuj wszystkie klawisze, Fn, skróty, gesty, kliknięcia i działanie po restarcie oraz wybudzeniu. stop: Przerwij przy cieczy, korozji, pękniętym ZIF, deformacji obudowy lub podejrzeniu spuchniętej baterii.','symptomEn: Individual keys, rows or the whole keyboard fail or type unexpected characters. focusEn: Compare on-screen/external keyboard and check layout and Fn/NumLock. causesEn: Keyboard/touchpad disabled by shortcut; input layout; driver; contamination; failed keyboard matrix; ribbon cable; liquid damage; EC/KBC issue. checksEn: 1) Check language layout, NumLock/Fn and disable shortcut. 2) Compare with an external keyboard. 3) Check whether the fault occurs before OS startup. 4) Record whether one key, a row or all keys fail. 5) Do not power on after liquid exposure. stepsEn: 1) Rule out settings and application. 2) Test in UEFI/vendor diagnostics if available. 3) A technician disconnects the battery and checks ribbon, ZIF latch, contacts and part number. 4) Assess liquid traces and EC/KBC if many keys fail. 5) Never force the ribbon or pry the latch with a metal blade. testsEn: There is no universal keyboard-matrix resistance test. The exact model pinout and documentation are required. repairEn: Correct settings/driver; clean or replace keyboard/touchpad per procedure and part number. Ribbon/connector or EC/KBC repair belongs to a specialist. verifyEn: Test every key, Fn, shortcuts, gestures, clicks and operation after restart and wake. stopEn: Stop for liquid, corrosion, broken ZIF latch, case deformation or suspected swollen battery.','',''),
('fault:FAULT-16','fault','Touchpad','Touchpad nie reaguje','Touchpad is unresponsive','symptom: Kursor nie porusza się, gesty nie działają albo touchpad jest okresowo wyłączany. focus: Sprawdź skrót funkcyjny, ustawienia i działanie zewnętrznej myszy. causes: Wyłączony touchpad/klawiatura skrótem; układ języka; sterownik; zabrudzona klawiatura; uszkodzona membrana/matryca klawiszy; taśma; zalanie; problem EC/KBC. checks: 1) Sprawdź układ języka, NumLock/Fn i skrót wyłączenia. 2) Porównaj z klawiaturą zewnętrzną. 3) Sprawdź, czy usterka występuje przed uruchomieniem systemu. 4) Zapisz, czy nie działa jeden klawisz, rząd czy całość. 5) Po zalaniu nie włączaj urządzenia. steps: 1) Wyklucz ustawienia i aplikację. 2) Sprawdź urządzenie w UEFI/diagnostyce producenta, jeśli dostępna. 3) Technik odłącza baterię i sprawdza taśmę, blokadę ZIF, styki i oznaczenie części. 4) Ocenia ślady cieczy i obwód EC/KBC, jeśli problem dotyczy wielu klawiszy. 5) Nie wkładaj taśmy na siłę i nie podnoś blokady metalowym ostrzem. tests: Nie ma uniwersalnego testu rezystancji matrycy klawiatury. Wymagane są pinout i dokumentacja konkretnego modelu. repair: Popraw ustawienia/sterownik; wyczyść lub wymień klawiaturę/touchpad zgodnie z procedurą i numerem części. Napraw taśmy/złącza lub EC/KBC powierz specjaliście. verify: Przetestuj wszystkie klawisze, Fn, skróty, gesty, kliknięcia i działanie po restarcie oraz wybudzeniu. stop: Przerwij przy cieczy, korozji, pękniętym ZIF, deformacji obudowy lub podejrzeniu spuchniętej baterii.','symptomEn: Pointer does not move, gestures fail or the touchpad is intermittently disabled. focusEn: Check function-key toggle, settings and an external mouse. causesEn: Keyboard/touchpad disabled by shortcut; input layout; driver; contamination; failed keyboard matrix; ribbon cable; liquid damage; EC/KBC issue. checksEn: 1) Check language layout, NumLock/Fn and disable shortcut. 2) Compare with an external keyboard. 3) Check whether the fault occurs before OS startup. 4) Record whether one key, a row or all keys fail. 5) Do not power on after liquid exposure. stepsEn: 1) Rule out settings and application. 2) Test in UEFI/vendor diagnostics if available. 3) A technician disconnects the battery and checks ribbon, ZIF latch, contacts and part number. 4) Assess liquid traces and EC/KBC if many keys fail. 5) Never force the ribbon or pry the latch with a metal blade. testsEn: There is no universal keyboard-matrix resistance test. The exact model pinout and documentation are required. repairEn: Correct settings/driver; clean or replace keyboard/touchpad per procedure and part number. Ribbon/connector or EC/KBC repair belongs to a specialist. verifyEn: Test every key, Fn, shortcuts, gestures, clicks and operation after restart and wake. stopEn: Stop for liquid, corrosion, broken ZIF latch, case deformation or suspected swollen battery.','',''),
('fault:FAULT-17','fault','USB-C / Power Delivery','USB-C nie ładuje lub nie przesyła obrazu','USB-C does not charge or output video','symptom: Port działa tylko w jednym kierunku, nie ładuje lub nie obsługuje monitora. focus: Sprawdź funkcje konkretnego portu, kabel, moc ładowarki i zgodność DP Alt Mode/Thunderbolt. causes: Uszkodzony kabel/akcesorium; ograniczona funkcja danego portu; zabrudzone lub wygięte styki; zabezpieczenie ESD/TVS; bezpiecznik/polyfuse; kontroler USB/PCH; niewłaściwy adapter lub wersja protokołu. checks: 1) Sprawdź inne akcesorium i znany sprawny kabel. 2) Wypróbuj drugi port. 3) Obejrzyj złącze bez wkładania metalowych przedmiotów. 4) Dla wideo sprawdź wejście i źródło monitora. 5) Dla USB-C potwierdź w specyfikacji obsługę danych, ładowania i obrazu oddzielnie. steps: 1) Zapisz urządzenie, kabel, port i dokładny objaw. 2) Sprawdź wykrywanie w systemie i komunikaty. 3) Technik ogląda styki, mocowanie i ochronę ESD. 4) Schemat wskazuje zasilanie portu, kontroler i linie danych. 5) Nie wykonuj pomiarów na pinach przy niepewnym pinoucie. tests: USB-C/HDMI/USB mają różne pinouty i warianty. Nie zakładaj, że kolory przewodów lub pinout z ogólnej planszy pasują do każdego kabla/gniazda. repair: Wymień uszkodzony kabel/adapter; napraw mechaniczne mocowanie złącza; wymień bezpiecznik lub ochronę dopiero po ustaleniu przyczyny. Uszkodzenia linii sygnałowych i kontrolera wymagają naprawy płyty. verify: Sprawdź kilka cykli podłączania, transfer danych lub obraz, stabilność zasilania oraz brak nagrzewania złącza. stop: Przerwij przy wygiętych pinach, iskrzeniu, nadpaleniu, wodzie lub nagrzewaniu kabla/portu.','symptomEn: Port works only one way, will not charge or does not support a display. focusEn: Check port capabilities, cable, charger wattage and DP Alt Mode/Thunderbolt support. causesEn: Faulty cable/accessory; port feature limitation; dirty or bent contacts; ESD/TVS protection; fuse/polyfuse; USB/PCH controller; incompatible adapter or protocol version. checksEn: 1) Test another accessory and known-good cable. 2) Try another port. 3) Inspect the connector without inserting metal objects. 4) For video, check monitor input/source. 5) For USB-C, verify data, charging and video capabilities separately in the specification. stepsEn: 1) Record device, cable, port and exact symptom. 2) Check OS detection and messages. 3) A technician inspects contacts, mounting and ESD protection. 4) The schematic identifies port power, controller and data lines. 5) Never probe pins with an uncertain pinout. testsEn: USB-C/HDMI/USB have different pinouts and variants. Do not assume wire colors or a generic chart match every cable/connector. repairEn: Replace a faulty cable/adapter; repair mechanical connector mounting; replace fuse/protection only after identifying the cause. Signal-line or controller damage requires board repair. verifyEn: Check multiple connect cycles, data transfer or video, stable power and no connector heating. stopEn: Stop for bent pins, arcing, burning, liquid or cable/port heating.','',''),
('fault:FAULT-18','fault','System i rozruch','Windows uruchamia się nieprawidłowo','Windows does not boot correctly','symptom: Komunikat boot device, pętla naprawy automatycznej, logo bez postępu lub czarny ekran. focus: Zapisz komunikat i zabezpiecz dane przed naprawą rozruchu lub reinstalacją. causes: Aktualizacja lub sterownik; uszkodzone pliki systemowe; błędny wpis rozruchu; brak miejsca; RAM/nośnik; konflikt oprogramowania; malware; nieprawidłowy tryb UEFI/Secure Boot. checks: 1) Zapisz kod i komunikat. 2) Zabezpiecz dane. 3) Ustal, czy UEFI wykrywa nośnik. 4) Odłącz niepotrzebne akcesoria. 5) Zanotuj ostatnie aktualizacje i zmiany. steps: 1) Oddziel problem sprzętowy od systemowego, sprawdzając POST/UEFI. 2) Sprawdź stan nośnika przed naprawą systemu. 3) Używaj środowiska odzyskiwania producenta/systemu i zachowaj logi. 4) Cofnij tylko konkretną, znaną zmianę (sterownik/aktualizacja), nie wykonuj wielu napraw naraz. 5) Przed reinstalacją potwierdź backup i klucz BitLocker. tests: SFC/DISM/CHKDSK nie zastępują diagnozy nośnika i nie powinny być pierwszym krokiem przy fizycznie uszkodzonym dysku. Zrzuty BSOD i logi są ważniejsze niż sam opis „nie działa”. repair: Naprawiaj przyczynowo: przywróć sterownik/aktualizację, popraw wpis boot, zwolnij miejsce bez usuwania nieznanych plików lub wymień potwierdzony sprzęt. Reinstalacja jest ostatecznością po kopii. verify: Wykonaj kilka restartów, sprawdź dziennik zdarzeń, aktualizacje, urządzenia, kopie danych i odtworzenie punktu przywracania/obrazu, jeśli wymagane. stop: Nie formatuj przy niepewnym stanie danych lub braku klucza BitLocker. Przerwij przy błędach odczytu, znikającym dysku lub podejrzeniu malware szyfrującego pliki.','symptomEn: Boot device error, automatic repair loop, frozen logo or black screen. focusEn: Record the message and protect data before boot repair or reinstall. causesEn: Update or driver; corrupted system files; invalid boot entry; low storage; RAM/drive fault; software conflict; malware; incorrect UEFI/Secure Boot mode. checksEn: 1) Record code and message. 2) Protect data. 3) Determine whether UEFI detects the drive. 4) Disconnect unnecessary peripherals. 5) Record recent updates and changes. stepsEn: 1) Separate hardware from OS by checking POST/UEFI. 2) Check drive health before OS repair. 3) Use vendor/OS recovery and retain logs. 4) Roll back one known change (driver/update); do not apply many repairs at once. 5) Confirm backup and BitLocker key before reinstalling. testsEn: SFC/DISM/CHKDSK do not replace drive diagnostics and should not be the first step on a physically failing drive. BSOD dumps and logs are more useful than “it does not work”. repairEn: Repair the cause: roll back driver/update, correct boot entry, free space without deleting unknown files or replace confirmed hardware. Reinstall only after backup and as a last resort. verifyEn: Perform several restarts; check Event Viewer, updates, devices, backups and restore-point/image recovery if required. stopEn: Do not format when data status is uncertain or BitLocker key is missing. Stop for read errors, disappearing drive or suspected file-encrypting malware.','',''),
('fault:FAULT-19','fault','Dyski i firmware','UEFI nie wykrywa dysku','UEFI does not detect the drive','symptom: Nośnik nie pojawia się na liście UEFI albo znika po restarcie. focus: Ustal interfejs, zgodność gniazda i czy problem wystąpił po zmianie ustawień. causes: Zużycie komórek NAND lub problemy kontrolera; błędy firmware; uszkodzony przewód/gniazdo; niekompatybilny interfejs SATA/NVMe; przegrzewanie; błędy systemu plików; zasilanie nośnika. checks: 1) Jeśli dane są ważne, ogranicz testy i zapisy. 2) Zapisz model nośnika i objawy. 3) Sprawdź, czy nośnik jest wykrywany w UEFI i systemie. 4) Zwróć uwagę na odgłosy mechaniczne HDD. 5) Przy stabilnym nośniku wykonaj kopię najważniejszych danych przed testami. steps: 1) Nie uruchamiaj wielokrotnie klikającego HDD. 2) Sprawdź kabel, port i osadzenie nośnika przy odłączonym zasilaniu. 3) Odczytaj SMART narzędziem producenta lub zaufanym narzędziem, nie traktując jednego parametru jako wyroku. 4) Rozróżnij problemy interfejsu, temperatury, firmware i powierzchni. 5) Przy błędach odczytu wykonaj obraz nośnika na inny sprawny dysk, jeśli stan na to pozwala. tests: SMART to wskaźnik, nie gwarancja sprawności. Testy powierzchniowe, benchmark i CHKDSK mogą pogorszyć sytuację niestabilnego nośnika. Przy niezastąpionych danych najpierw konsultacja z odzyskiem danych. repair: Po bezpiecznej kopii: wymień potwierdzony przewód/adapter, popraw montaż lub wymień nośnik. Firmware aktualizuj tylko według instrukcji producenta i przy stabilnym zasilaniu. Nie formatuj, jeśli dane nie są zabezpieczone. verify: Sprawdź ponowne wykrywanie po zimnym starcie, SMART, temperaturę, transfer dużego pliku oraz odczyt kopii. Zweryfikuj kopię przez otwarcie wybranych plików. stop: Przerwij przy klikaniu/stukaniu HDD, zapachu spalenizny, nadmiernym nagrzaniu, znikaniu nośnika podczas odczytu lub danych o dużej wartości.','symptomEn: Drive is missing from UEFI or disappears after restart. focusEn: Identify interface, slot compatibility and whether the issue followed a settings change. causesEn: NAND wear or controller issues; firmware errors; damaged cable/connector; SATA/NVMe incompatibility; overheating; filesystem errors; drive power problems. checksEn: 1) If data matters, minimize tests and writes. 2) Record drive model and symptoms. 3) Check detection in UEFI and OS. 4) Listen for mechanical HDD noises. 5) For a stable drive, copy critical data before testing. stepsEn: 1) Do not repeatedly power a clicking HDD. 2) Inspect cable, port and seating with power disconnected. 3) Read SMART using vendor or trusted tools; no single field is a complete verdict. 4) Separate interface, thermal, firmware and media faults. 5) For read errors, image the drive to another healthy disk if its condition permits. testsEn: SMART is an indicator, not a guarantee. Surface tests, benchmarks and CHKDSK can worsen an unstable drive. For irreplaceable data, consult a recovery specialist first. repairEn: After a safe backup: replace a confirmed cable/adapter, reseat or replace the drive. Update firmware only per vendor instructions and with stable power. Do not format before data is secured. verifyEn: Check detection after cold boot, SMART, temperature, large-file transfer and backup readability. Verify the backup by opening sample files. stopEn: Stop for HDD clicking/knocking, burning smell, overheating, drive disappearing during reads or high-value data.','',''),
('fault:FAULT-20','fault','Wydajność i system','Komputer nagle działa bardzo wolno','Computer suddenly becomes very slow','symptom: Opóźnienia, długi start, 100% użycia dysku/CPU lub zawieszanie aplikacji. focus: Zapisz kiedy występuje spowolnienie; sprawdź użycie zasobów, temperatury i wolne miejsce. causes: Aktualizacja lub sterownik; uszkodzone pliki systemowe; błędny wpis rozruchu; brak miejsca; RAM/nośnik; konflikt oprogramowania; malware; nieprawidłowy tryb UEFI/Secure Boot. checks: 1) Zapisz kod i komunikat. 2) Zabezpiecz dane. 3) Ustal, czy UEFI wykrywa nośnik. 4) Odłącz niepotrzebne akcesoria. 5) Zanotuj ostatnie aktualizacje i zmiany. steps: 1) Oddziel problem sprzętowy od systemowego, sprawdzając POST/UEFI. 2) Sprawdź stan nośnika przed naprawą systemu. 3) Używaj środowiska odzyskiwania producenta/systemu i zachowaj logi. 4) Cofnij tylko konkretną, znaną zmianę (sterownik/aktualizacja), nie wykonuj wielu napraw naraz. 5) Przed reinstalacją potwierdź backup i klucz BitLocker. tests: SFC/DISM/CHKDSK nie zastępują diagnozy nośnika i nie powinny być pierwszym krokiem przy fizycznie uszkodzonym dysku. Zrzuty BSOD i logi są ważniejsze niż sam opis „nie działa”. repair: Naprawiaj przyczynowo: przywróć sterownik/aktualizację, popraw wpis boot, zwolnij miejsce bez usuwania nieznanych plików lub wymień potwierdzony sprzęt. Reinstalacja jest ostatecznością po kopii. verify: Wykonaj kilka restartów, sprawdź dziennik zdarzeń, aktualizacje, urządzenia, kopie danych i odtworzenie punktu przywracania/obrazu, jeśli wymagane. stop: Nie formatuj przy niepewnym stanie danych lub braku klucza BitLocker. Przerwij przy błędach odczytu, znikającym dysku lub podejrzeniu malware szyfrującego pliki.','symptomEn: Lag, slow boot, 100% disk/CPU use or application freezes. focusEn: Record when slowdown occurs; inspect resource use, temperature and free space. causesEn: Update or driver; corrupted system files; invalid boot entry; low storage; RAM/drive fault; software conflict; malware; incorrect UEFI/Secure Boot mode. checksEn: 1) Record code and message. 2) Protect data. 3) Determine whether UEFI detects the drive. 4) Disconnect unnecessary peripherals. 5) Record recent updates and changes. stepsEn: 1) Separate hardware from OS by checking POST/UEFI. 2) Check drive health before OS repair. 3) Use vendor/OS recovery and retain logs. 4) Roll back one known change (driver/update); do not apply many repairs at once. 5) Confirm backup and BitLocker key before reinstalling. testsEn: SFC/DISM/CHKDSK do not replace drive diagnostics and should not be the first step on a physically failing drive. BSOD dumps and logs are more useful than “it does not work”. repairEn: Repair the cause: roll back driver/update, correct boot entry, free space without deleting unknown files or replace confirmed hardware. Reinstall only after backup and as a last resort. verifyEn: Perform several restarts; check Event Viewer, updates, devices, backups and restore-point/image recovery if required. stopEn: Do not format when data status is uncertain or BitLocker key is missing. Stop for read errors, disappearing drive or suspected file-encrypting malware.','',''),
('fault:FAULT-21','fault','Windows i stabilność','Niebieski ekran BSOD','Blue screen / BSOD','symptom: System zapisuje kod stop, restartuje się lub tworzy zrzut pamięci. focus: Zapisz kod, czas i ostatnie zmiany sprzętu/sterowników. causes: Aktualizacja lub sterownik; uszkodzone pliki systemowe; błędny wpis rozruchu; brak miejsca; RAM/nośnik; konflikt oprogramowania; malware; nieprawidłowy tryb UEFI/Secure Boot. checks: 1) Zapisz kod i komunikat. 2) Zabezpiecz dane. 3) Ustal, czy UEFI wykrywa nośnik. 4) Odłącz niepotrzebne akcesoria. 5) Zanotuj ostatnie aktualizacje i zmiany. steps: 1) Oddziel problem sprzętowy od systemowego, sprawdzając POST/UEFI. 2) Sprawdź stan nośnika przed naprawą systemu. 3) Używaj środowiska odzyskiwania producenta/systemu i zachowaj logi. 4) Cofnij tylko konkretną, znaną zmianę (sterownik/aktualizacja), nie wykonuj wielu napraw naraz. 5) Przed reinstalacją potwierdź backup i klucz BitLocker. tests: SFC/DISM/CHKDSK nie zastępują diagnozy nośnika i nie powinny być pierwszym krokiem przy fizycznie uszkodzonym dysku. Zrzuty BSOD i logi są ważniejsze niż sam opis „nie działa”. repair: Naprawiaj przyczynowo: przywróć sterownik/aktualizację, popraw wpis boot, zwolnij miejsce bez usuwania nieznanych plików lub wymień potwierdzony sprzęt. Reinstalacja jest ostatecznością po kopii. verify: Wykonaj kilka restartów, sprawdź dziennik zdarzeń, aktualizacje, urządzenia, kopie danych i odtworzenie punktu przywracania/obrazu, jeśli wymagane. stop: Nie formatuj przy niepewnym stanie danych lub braku klucza BitLocker. Przerwij przy błędach odczytu, znikającym dysku lub podejrzeniu malware szyfrującego pliki.','symptomEn: System reports a stop code, restarts or creates a memory dump. focusEn: Record stop code, time and recent hardware/driver changes. causesEn: Update or driver; corrupted system files; invalid boot entry; low storage; RAM/drive fault; software conflict; malware; incorrect UEFI/Secure Boot mode. checksEn: 1) Record code and message. 2) Protect data. 3) Determine whether UEFI detects the drive. 4) Disconnect unnecessary peripherals. 5) Record recent updates and changes. stepsEn: 1) Separate hardware from OS by checking POST/UEFI. 2) Check drive health before OS repair. 3) Use vendor/OS recovery and retain logs. 4) Roll back one known change (driver/update); do not apply many repairs at once. 5) Confirm backup and BitLocker key before reinstalling. testsEn: SFC/DISM/CHKDSK do not replace drive diagnostics and should not be the first step on a physically failing drive. BSOD dumps and logs are more useful than “it does not work”. repairEn: Repair the cause: roll back driver/update, correct boot entry, free space without deleting unknown files or replace confirmed hardware. Reinstall only after backup and as a last resort. verifyEn: Perform several restarts; check Event Viewer, updates, devices, backups and restore-point/image recovery if required. stopEn: Do not format when data status is uncertain or BitLocker key is missing. Stop for read errors, disappearing drive or suspected file-encrypting malware.','',''),
('fault:FAULT-22','fault','Zasilanie i temperatura','Komputer sam się wyłącza','Computer shuts down by itself','symptom: Wyłączenie bez ostrzeżenia, częściej przy obciążeniu, grzaniu albo ruchu przewodu. focus: Rozdziel problem termiczny, zasilanie, baterię i błąd systemowy; nie powtarzaj testów obciążenia. causes: Brak zasilania w gniazdku lub przewodzie; niezgodny/uszkodzony adapter; uszkodzone DC-IN; bezpiecznik wejściowy; MOSFET lub kontroler ładowania; brak napięć czuwania; EC/KBC nie rozpoczyna sekwencji; zwarcie na linii zasilania. checks: 1) Sprawdź gniazdko innym urządzeniem. 2) Obejrzyj przewód, wtyk i gniazdo bez poruszania nadpalonym złączem. 3) Potwierdź napięcie, moc, polaryzację i identyfikację oryginalnego adaptera. 4) Odłącz akcesoria USB i stację dokującą. 5) Zapisz reakcję LED i przycisku Power. steps: 1) Potwierdź model, dokładną rewizję płyty i zasilacz. 2) Obejrzyj płytę pod kątem korozji, pęknięcia gniazda, nadpaleń i śladów cieczy. 3) Ustal, czy objaw to całkowity brak reakcji, krótkie mignięcie czy pętla startu. 4) Technik identyfikuje DC-IN, bezpiecznik, MOSFET-y, charger i linie standby na schemacie/BoardView. 5) Dopiero potem wykonuje pomiary zgodne z dokumentacją, z kontrolowanymi warunkami. tests: Przed pomiarem potwierdź punkt GND, zakres miernika i stan sond. Rezystancję/ciągłość sprawdzaj wyłącznie po odłączeniu wszystkich źródeł zasilania i rozładowaniu według procedury. Napięć 3V/5V/VIN nie traktuj jako uniwersalnego pinoutu — porównuj z konkretną płytą. repair: Napraw lub wymień wyłącznie element potwierdzony pomiarami i dokumentacją: przewód/adapter, gniazdo, bezpiecznik, element toru wejściowego lub kontroler. Po wymianie usuń przyczynę przeciążenia; nigdy nie zwieraj bezpiecznika. verify: Wykonaj zimny start, kilka kontrolowanych uruchomień, sprawdź stabilność zasilania, ładowanie (jeśli występuje), POST, obraz i brak nadmiernego nagrzewania. Zapisz użyty adapter i wyniki. stop: Przerwij przy dymie, zapachu spalenizny, iskrzeniu, gorącym złączu, cieczy, spuchniętej baterii lub nieznanym zwarciu. Nie otwieraj zasilacza sieciowego.','symptomEn: Unexpected shutdown, often under load, heat or cable movement. focusEn: Separate thermal, power, battery and OS causes; do not repeat stress tests. causesEn: Wall outlet or cable failure; incorrect/faulty adapter; damaged DC-in; input fuse; MOSFET or charger controller; missing standby rails; EC/KBC does not start the sequence; shorted power rail. checksEn: 1) Verify the outlet with another device. 2) Inspect cable, plug and socket without moving a burnt connector. 3) Confirm the original adapter voltage, wattage, polarity and identification. 4) Disconnect USB accessories and dock. 5) Record LED and power-button response. stepsEn: 1) Confirm model, exact board revision and adapter. 2) Inspect for corrosion, cracked jack, burns and liquid traces. 3) Classify the symptom: no response, brief flash or boot loop. 4) A technician identifies DC-in, fuse, MOSFETs, charger and standby rails in the schematic/BoardView. 5) Only then perform model-documented measurements under controlled conditions. testsEn: Before measuring, confirm GND, meter range and probe condition. Measure resistance/continuity only after disconnecting every power source and following the discharge procedure. Do not treat 3V/5V/VIN as a universal pinout; compare with the exact board. repairEn: Repair or replace only a component confirmed by measurements and documentation: cable/adapter, jack, fuse, input-stage component or controller. Remove the cause of overload; never bridge a fuse. verifyEn: Perform a cold start and several controlled power-ons; verify stable power, charging if applicable, POST, display and absence of abnormal heating. Record the adapter and results. stopEn: Stop for smoke, burning smell, arcing, hot connector, liquid, swollen battery or an unidentified short. Never open a mains PSU.','',''),
('fault:FAULT-23','fault','Sieć','Wi-Fi połączone, ale brak internetu','Wi-Fi connected but no internet','symptom: Urządzenie łączy się z routerem, ale strony lub usługi nie działają. focus: Porównaj kilka stron, aplikację i drugie urządzenie; sprawdź status WAN routera. causes: Tryb samolotowy lub przełącznik radiowy; router/AP; błędne hasło; sterownik; usługa systemowa; oszczędzanie energii; antena lub karta Wi-Fi; DHCP/DNS/WAN. checks: 1) Sprawdź tryb samolotowy i fizyczny przełącznik. 2) Porównaj telefon w tej samej sieci. 3) Sprawdź laptop w innej sieci. 4) Zapisz komunikat błędu i siłę sygnału. 5) Uruchom ponownie router tylko po zapisaniu jego statusu i upewnieniu się, że nie wykonuje aktualizacji. steps: 1) Ustal, czy problem dotyczy jednej sieci, wszystkich sieci czy samej karty. 2) Sprawdź Menedżer urządzeń i kod urządzenia. 3) Przywróć właściwy sterownik z witryny producenta po zidentyfikowaniu karty. 4) Sprawdź adres IP, bramę i DNS. 5) Jeśli sygnał jest słaby w kilku lokalizacjach, technik sprawdza anteny i przewody. tests: Zapisz wynik ipconfig /all, ping do bramy i rozpoznawanie nazw DNS. Nie wyłączaj zabezpieczeń routera ani zapory jako „testu” na stałe. repair: Popraw ustawienia sieci, hasło, sterownik lub konfigurację routera. Kartę/antenę wymieniaj dopiero po potwierdzeniu sprzętowym i zgodności z platformą. verify: Sprawdź połączenie po restarcie, transfer pliku, roaming, DNS i stabilność przez kilka minut w zwykłym miejscu użytkowania. stop: Przerwij przy uszkodzonym złączu antenowym, śladach cieczy lub konieczności otwarcia zasilacza/routera. Nie resetuj routera do ustawień fabrycznych bez kopii konfiguracji.','symptomEn: Device connects to the router but websites or services fail. focusEn: Compare multiple sites, an app and another device; check router WAN status. causesEn: Airplane mode or radio switch; router/AP; incorrect password; driver; OS service; power saving; antenna or Wi-Fi card; DHCP/DNS/WAN. checksEn: 1) Check airplane mode and physical switch. 2) Compare a phone on the same network. 3) Test the laptop on another network. 4) Record error message and signal strength. 5) Restart the router only after recording its status and confirming it is not updating. stepsEn: 1) Determine whether the problem affects one network, all networks or the adapter itself. 2) Check Device Manager and device code. 3) Install the correct vendor driver after identifying the adapter. 4) Check IP address, gateway and DNS. 5) If signal is weak in multiple locations, a technician inspects antennas and cables. testsEn: Record ipconfig /all, gateway ping and DNS resolution. Do not permanently disable router security or firewall as a “test”. repairEn: Correct network settings, password, driver or router configuration. Replace adapter/antenna only after hardware confirmation and platform compatibility check. verifyEn: Check connection after restart, file transfer, roaming, DNS and stability for several minutes in the normal use location. stopEn: Stop for damaged antenna connector, liquid traces or any need to open a PSU/router. Do not factory-reset a router without configuration backup.','',''),
('fault:FAULT-24','fault','Bateria i zasilanie','Bateria szybko się rozładowuje','Battery drains quickly','symptom: Krótki czas pracy, nagły spadek procentów, duże zużycie w uśpieniu. focus: Porównaj zużycie przy podobnym obciążeniu i sprawdź raport kondycji baterii. causes: Limit ładowania w oprogramowaniu; niezgodny adapter lub kabel USB-C PD; zużyte ogniwa; błędna komunikacja baterii; gniazdo DC-IN; kontroler ładowania; problem z czujnikiem temperatury. checks: 1) Sprawdź, czy ładowanie nie ma ustawionego limitu (np. ochrona baterii). 2) Użyj zasilacza o zgodnych parametrach. 3) Zapisz status baterii i raport kondycji. 4) Obejrzyj obudowę pod kątem wybrzuszeń. 5) Sprawdź, czy problem występuje po pełnym wyłączeniu i ponownym starcie. steps: 1) Potwierdź model baterii i adaptera. 2) Porównaj status ładowania w systemie i UEFI, jeśli dostępny. 3) Technik ocenia gniazdo, linie identyfikacji i układ ładowania na schemacie. 4) Sprawdza komunikację BMS oraz czujnik temperatury zgodnie z dokumentacją. 5) Nie wykonuje się „naprawy” przez mostkowanie baterii lub bezpieczników. tests: Nie rozbieraj pakietu Li-ion/Li-pol i nie mierz ogniw bez odpowiedniego wyposażenia. Każdy pomiar na płycie musi być zgodny z dokumentacją modelu. Spuchniętej baterii nie testuj ani nie ładuj. repair: Usuń przyczynę: konfiguracja limitu, zgodny adapter/kabel, naprawa gniazda lub obwodu ładowania, wymiana baterii na zatwierdzony numer części. Nie stosuj zamiennika bez zgodności napięcia, BMS i mechaniki. verify: Sprawdź wykrywanie baterii, zmianę poziomu w czasie, ładowanie przy wyłączonym i włączonym urządzeniu, temperaturę i komunikaty systemu. stop: Spuchnięcie, przebicie, wyciek, syczenie, zapach chemiczny lub nadmierne grzanie baterii oznaczają STOP. Nie ściskaj, nie przekłuwaj i nie wrzucaj do zwykłych odpadów.','symptomEn: Short runtime, sudden percentage drops or high sleep drain. focusEn: Compare drain under similar load and inspect battery health report. causesEn: Charge threshold in software; incompatible adapter or USB-C PD cable; worn cells; battery communication fault; DC-in jack; charger controller; temperature-sensor issue. checksEn: 1) Check whether charging is limited by a battery-protection feature. 2) Use an adapter with matching specifications. 3) Record battery status and health report. 4) Inspect for swelling. 5) Check after a full shutdown and restart. stepsEn: 1) Confirm battery and adapter models. 2) Compare charging status in OS and UEFI if available. 3) A technician checks jack, identification lines and charger circuit against the schematic. 4) Check BMS communication and temperature sensor per documentation. 5) Never “repair” by bridging battery protection or fuses. testsEn: Do not dismantle a Li-ion/Li-pol pack or probe cells without proper equipment. Board measurements must follow exact model documentation. Never test or charge a swollen battery. repairEn: Correct the cause: charge limit setting, compatible adapter/cable, jack or charging-circuit repair, or battery replacement with approved part number. Do not use a substitute without voltage, BMS and mechanical compatibility. verifyEn: Check battery detection, percentage change over time, charging while off/on, temperature and OS messages. stopEn: Swelling, puncture, leakage, hissing, chemical odor or excessive battery heat mean STOP. Do not squeeze, puncture or place in ordinary waste.','',''),
('fault:FAULT-25','fault','POST i diagnostyka','Komputer wydaje sygnały dźwiękowe przy starcie','Computer beeps at startup','symptom: Sygnały beep występują po włączeniu i mogą wskazywać etap POST. focus: Nagraj dokładną sekwencję i ustal producenta BIOS/płyty; kody nie są uniwersalne. causes: Niekompatybilny moduł DDR; źle osadzony DIMM/SODIMM; zabrudzone lub uszkodzone styki; uszkodzony slot; nieprawidłowe ustawienia pamięci/UEFI; problem kontrolera pamięci w CPU lub płycie; nieaktualna/niezgodna wersja firmware. checks: 1) Zapisz sekwencję diod/beep i kod POST. 2) Sprawdź typ DDR, pojemność i specyfikację płyty. 3) Odłącz zasilanie przed wyjmowaniem RAM. 4) Porównaj moduły pojedynczo i sloty zgodnie z instrukcją. 5) Po zmianach pozwól na ewentualny trening pamięci. steps: 1) Przywróć konfigurację minimalną zgodną z dokumentacją. 2) Testuj pojedynczy, znany sprawny moduł w zalecanym slocie. 3) Zapisuj wynik każdej kombinacji moduł/slot. 4) Wyklucz profil XMP/EXPO i niestandardowe taktowanie, wracając do ustawień bezpiecznych. 5) Jeśli objaw pozostaje, technik analizuje zasilanie RAM, linie sygnałowe i kontroler pamięci. tests: Test pamięci uruchamiaj dopiero po ustabilizowaniu konfiguracji. Kod beep jest zależny od BIOS/producenta — interpretuj go z instrukcji danego modelu. Nie mierz linii sygnałowych bez schematu i właściwego sprzętu. repair: Wymień moduł tylko po potwierdzeniu usterki w powtarzalnym teście. Uszkodzony slot lub ścieżka wymaga naprawy płyty; aktualizację BIOS wykonuj wyłącznie, gdy dokumentacja producenta wskazuje taki przypadek i zasilanie jest stabilne. verify: Wykonaj pełny test pamięci, kilka zimnych startów, sprawdź wykrytą pojemność, kanały i stabilność pod normalnym obciążeniem. stop: Przerwij, gdy pojawia się zapach spalenizny, nadmierne nagrzanie modułu/slotu lub uszkodzenie mechaniczne. Nie wkładaj i nie wyjmuj pamięci przy podłączonym zasilaniu.','symptomEn: Beep codes occur at power-on and may indicate a POST stage. focusEn: Record the exact pattern and identify BIOS/board vendor; beep codes are not universal. causesEn: Incompatible DDR module; poorly seated DIMM/SODIMM; dirty or damaged contacts; faulty slot; incorrect memory/UEFI settings; CPU memory-controller or motherboard fault; firmware compatibility issue. checksEn: 1) Record LED/beep sequence and POST code. 2) Check DDR type, capacity and board specification. 3) Remove power before reseating RAM. 4) Compare modules individually and slots per manual. 5) Allow memory training after configuration changes. stepsEn: 1) Return to a documented minimal configuration. 2) Test one known-good module in the recommended slot. 3) Record every module/slot combination. 4) Rule out XMP/EXPO and custom timings by returning to safe defaults. 5) If the issue remains, a technician checks RAM power, signal lines and memory controller. testsEn: Run memory tests only after the configuration is stable. Beep codes depend on BIOS/vendor; interpret them using the exact model manual. Do not probe signal lines without a schematic and proper equipment. repairEn: Replace a module only after repeatable confirmation. A faulty slot or trace requires board repair; update BIOS only when vendor documentation supports it and power is stable. verifyEn: Run a full memory test and several cold starts; confirm detected capacity, channels and stability under normal load. stopEn: Stop if there is a burning smell, abnormal module/slot heating or mechanical damage. Never insert or remove memory while powered.','',''),
('fault:FAULT-26','fault','Obraz i wyjścia wideo','Nie działa monitor zewnętrzny','External monitor does not work','symptom: Monitor zgłasza brak sygnału, nie wykrywa rozdzielczości lub obraz miga. focus: Sprawdź wybrane wejście, przewód, adapter i to, czy dany port obsługuje obraz. causes: Jasność/tryb wyświetlania; uszkodzony panel; taśma eDP/LVDS; brak podświetlenia; złącze lub bezpiecznik podświetlenia; GPU/ścieżka obrazu; sterownik; monitor lub kabel. checks: 1) Zwiększ jasność i wyłącz tryb oszczędzania. 2) Sprawdź, czy widać logo/UEFI. 3) Porównaj obraz na zewnętrznym ekranie. 4) Sprawdź wejście monitora i kabel. 5) Nie ruszaj pokrywą, jeżeli obraz reaguje na jej położenie. steps: 1) Ustal, czy problem występuje już w UEFI, czy dopiero po sterowniku. 2) Zapisz wynik testu zewnętrznego monitora. 3) Technik sprawdza złącze panelu, osadzenie i zgodność przewodu po odłączeniu baterii. 4) Schemat identyfikuje linie zasilania panelu/podświetlenia oraz zabezpieczenia. 5) Weryfikuj panel i przewód na modelu zgodnym, nie na podstawie samego kształtu wtyku. tests: Nie podawaj napięć podświetlenia ani pinów eDP uniwersalnie. Pomiar na złączu panelu jest zadaniem technika: niewłaściwa sonda może spowodować zwarcie i uszkodzić panel lub płytę. repair: Najpierw przywróć właściwe ustawienia/sterownik. Części wymieniaj dopiero po potwierdzeniu: kabel, panel, złącze lub element toru podświetlenia. Napraw mocowań i zawiasów nie odkładaj, jeśli przewód jest naprężony. verify: Sprawdź obraz w UEFI i systemie, kilka poziomów jasności, ruch pokrywy w normalnym zakresie, monitor zewnętrzny oraz brak migotania po wybudzeniu. stop: Przerwij przy pękniętej matrycy, odsłoniętym przewodzie, iskrzeniu, nadpalonym złączu lub konieczności pomiaru bez schematu.','symptomEn: Monitor reports no signal, misses resolution or flickers. focusEn: Check selected input, cable, adapter and whether the port supports video. causesEn: Brightness/display mode; faulty panel; eDP/LVDS cable; backlight failure; connector or backlight fuse; GPU/display path; driver; monitor or cable. checksEn: 1) Increase brightness and disable power saving. 2) Check whether logo/UEFI appears. 3) Compare with an external display. 4) Check monitor input and cable. 5) Do not move the lid if image changes with its angle. stepsEn: 1) Determine whether the problem exists in UEFI or only after the driver loads. 2) Record external-monitor results. 3) A technician inspects panel connector, seating and cable compatibility after disconnecting the battery. 4) The schematic identifies panel/backlight power rails and protection. 5) Verify panel and cable compatibility for the exact model, not by connector shape alone. testsEn: Do not assume universal backlight voltages or eDP pins. Panel-connector measurements are technician work; a misplaced probe can short and damage the panel or board. repairEn: First restore correct settings/driver. Replace parts only after confirmation: cable, panel, connector or backlight-stage component. Do not delay hinge/mount repairs if the cable is under tension. verifyEn: Verify image in UEFI and OS, several brightness levels, normal lid movement, external display and no flicker after wake. stopEn: Stop for cracked panel, exposed cable, arcing, burnt connector or any measurement without the exact schematic.','',''),
('fault:FAULT-27','fault','Zasilanie i POST','Komputer uruchamia się dopiero po kilku próbach','Computer starts only after several attempts','symptom: Start zależy od liczby prób, czasu odłączenia zasilania lub temperatury. focus: Nie maskuj problemu wielokrotnym włączaniem; zapisuj sekwencję kontrolek i warunki. causes: Brak zasilania w gniazdku lub przewodzie; niezgodny/uszkodzony adapter; uszkodzone DC-IN; bezpiecznik wejściowy; MOSFET lub kontroler ładowania; brak napięć czuwania; EC/KBC nie rozpoczyna sekwencji; zwarcie na linii zasilania. checks: 1) Sprawdź gniazdko innym urządzeniem. 2) Obejrzyj przewód, wtyk i gniazdo bez poruszania nadpalonym złączem. 3) Potwierdź napięcie, moc, polaryzację i identyfikację oryginalnego adaptera. 4) Odłącz akcesoria USB i stację dokującą. 5) Zapisz reakcję LED i przycisku Power. steps: 1) Potwierdź model, dokładną rewizję płyty i zasilacz. 2) Obejrzyj płytę pod kątem korozji, pęknięcia gniazda, nadpaleń i śladów cieczy. 3) Ustal, czy objaw to całkowity brak reakcji, krótkie mignięcie czy pętla startu. 4) Technik identyfikuje DC-IN, bezpiecznik, MOSFET-y, charger i linie standby na schemacie/BoardView. 5) Dopiero potem wykonuje pomiary zgodne z dokumentacją, z kontrolowanymi warunkami. tests: Przed pomiarem potwierdź punkt GND, zakres miernika i stan sond. Rezystancję/ciągłość sprawdzaj wyłącznie po odłączeniu wszystkich źródeł zasilania i rozładowaniu według procedury. Napięć 3V/5V/VIN nie traktuj jako uniwersalnego pinoutu — porównuj z konkretną płytą. repair: Napraw lub wymień wyłącznie element potwierdzony pomiarami i dokumentacją: przewód/adapter, gniazdo, bezpiecznik, element toru wejściowego lub kontroler. Po wymianie usuń przyczynę przeciążenia; nigdy nie zwieraj bezpiecznika. verify: Wykonaj zimny start, kilka kontrolowanych uruchomień, sprawdź stabilność zasilania, ładowanie (jeśli występuje), POST, obraz i brak nadmiernego nagrzewania. Zapisz użyty adapter i wyniki. stop: Przerwij przy dymie, zapachu spalenizny, iskrzeniu, gorącym złączu, cieczy, spuchniętej baterii lub nieznanym zwarciu. Nie otwieraj zasilacza sieciowego.','symptomEn: Startup depends on attempt count, time without power or temperature. focusEn: Do not mask the fault by repeated power cycling; record LEDs and conditions. causesEn: Wall outlet or cable failure; incorrect/faulty adapter; damaged DC-in; input fuse; MOSFET or charger controller; missing standby rails; EC/KBC does not start the sequence; shorted power rail. checksEn: 1) Verify the outlet with another device. 2) Inspect cable, plug and socket without moving a burnt connector. 3) Confirm the original adapter voltage, wattage, polarity and identification. 4) Disconnect USB accessories and dock. 5) Record LED and power-button response. stepsEn: 1) Confirm model, exact board revision and adapter. 2) Inspect for corrosion, cracked jack, burns and liquid traces. 3) Classify the symptom: no response, brief flash or boot loop. 4) A technician identifies DC-in, fuse, MOSFETs, charger and standby rails in the schematic/BoardView. 5) Only then perform model-documented measurements under controlled conditions. testsEn: Before measuring, confirm GND, meter range and probe condition. Measure resistance/continuity only after disconnecting every power source and following the discharge procedure. Do not treat 3V/5V/VIN as a universal pinout; compare with the exact board. repairEn: Repair or replace only a component confirmed by measurements and documentation: cable/adapter, jack, fuse, input-stage component or controller. Remove the cause of overload; never bridge a fuse. verifyEn: Perform a cold start and several controlled power-ons; verify stable power, charging if applicable, POST, display and absence of abnormal heating. Record the adapter and results. stopEn: Stop for smoke, burning smell, arcing, hot connector, liquid, swollen battery or an unidentified short. Never open a mains PSU.','',''),
('fault:FAULT-28','fault','Pamięć RAM','Nowa pamięć RAM nie jest wykrywana','New RAM is not detected','symptom: Pojemność się nie zmienia, komputer nie przechodzi POST lub działa tylko na jednej kości. focus: Zweryfikuj generację DDR, format, pojemność, obsługę platformy i listę zgodności. causes: Niekompatybilny moduł DDR; źle osadzony DIMM/SODIMM; zabrudzone lub uszkodzone styki; uszkodzony slot; nieprawidłowe ustawienia pamięci/UEFI; problem kontrolera pamięci w CPU lub płycie; nieaktualna/niezgodna wersja firmware. checks: 1) Zapisz sekwencję diod/beep i kod POST. 2) Sprawdź typ DDR, pojemność i specyfikację płyty. 3) Odłącz zasilanie przed wyjmowaniem RAM. 4) Porównaj moduły pojedynczo i sloty zgodnie z instrukcją. 5) Po zmianach pozwól na ewentualny trening pamięci. steps: 1) Przywróć konfigurację minimalną zgodną z dokumentacją. 2) Testuj pojedynczy, znany sprawny moduł w zalecanym slocie. 3) Zapisuj wynik każdej kombinacji moduł/slot. 4) Wyklucz profil XMP/EXPO i niestandardowe taktowanie, wracając do ustawień bezpiecznych. 5) Jeśli objaw pozostaje, technik analizuje zasilanie RAM, linie sygnałowe i kontroler pamięci. tests: Test pamięci uruchamiaj dopiero po ustabilizowaniu konfiguracji. Kod beep jest zależny od BIOS/producenta — interpretuj go z instrukcji danego modelu. Nie mierz linii sygnałowych bez schematu i właściwego sprzętu. repair: Wymień moduł tylko po potwierdzeniu usterki w powtarzalnym teście. Uszkodzony slot lub ścieżka wymaga naprawy płyty; aktualizację BIOS wykonuj wyłącznie, gdy dokumentacja producenta wskazuje taki przypadek i zasilanie jest stabilne. verify: Wykonaj pełny test pamięci, kilka zimnych startów, sprawdź wykrytą pojemność, kanały i stabilność pod normalnym obciążeniem. stop: Przerwij, gdy pojawia się zapach spalenizny, nadmierne nagrzanie modułu/slotu lub uszkodzenie mechaniczne. Nie wkładaj i nie wyjmuj pamięci przy podłączonym zasilaniu.','symptomEn: Capacity does not change, system fails POST or works with only one module. focusEn: Verify DDR generation, form factor, capacity, platform support and compatibility list. causesEn: Incompatible DDR module; poorly seated DIMM/SODIMM; dirty or damaged contacts; faulty slot; incorrect memory/UEFI settings; CPU memory-controller or motherboard fault; firmware compatibility issue. checksEn: 1) Record LED/beep sequence and POST code. 2) Check DDR type, capacity and board specification. 3) Remove power before reseating RAM. 4) Compare modules individually and slots per manual. 5) Allow memory training after configuration changes. stepsEn: 1) Return to a documented minimal configuration. 2) Test one known-good module in the recommended slot. 3) Record every module/slot combination. 4) Rule out XMP/EXPO and custom timings by returning to safe defaults. 5) If the issue remains, a technician checks RAM power, signal lines and memory controller. testsEn: Run memory tests only after the configuration is stable. Beep codes depend on BIOS/vendor; interpret them using the exact model manual. Do not probe signal lines without a schematic and proper equipment. repairEn: Replace a module only after repeatable confirmation. A faulty slot or trace requires board repair; update BIOS only when vendor documentation supports it and power is stable. verifyEn: Run a full memory test and several cold starts; confirm detected capacity, channels and stability under normal load. stopEn: Stop if there is a burning smell, abnormal module/slot heating or mechanical damage. Never insert or remove memory while powered.','',''),
('fault:FAULT-29','fault','Dyski i zgodność','Nowy dysk M.2 nie działa','New M.2 drive does not work','symptom: Dysk nie jest wykrywany, slot nie działa albo nośnik jest wykrywany tylko w określonym trybie. focus: M.2 opisuje format; ustal, czy gniazdo obsługuje SATA, NVMe czy oba warianty. causes: Zużycie komórek NAND lub problemy kontrolera; błędy firmware; uszkodzony przewód/gniazdo; niekompatybilny interfejs SATA/NVMe; przegrzewanie; błędy systemu plików; zasilanie nośnika. checks: 1) Jeśli dane są ważne, ogranicz testy i zapisy. 2) Zapisz model nośnika i objawy. 3) Sprawdź, czy nośnik jest wykrywany w UEFI i systemie. 4) Zwróć uwagę na odgłosy mechaniczne HDD. 5) Przy stabilnym nośniku wykonaj kopię najważniejszych danych przed testami. steps: 1) Nie uruchamiaj wielokrotnie klikającego HDD. 2) Sprawdź kabel, port i osadzenie nośnika przy odłączonym zasilaniu. 3) Odczytaj SMART narzędziem producenta lub zaufanym narzędziem, nie traktując jednego parametru jako wyroku. 4) Rozróżnij problemy interfejsu, temperatury, firmware i powierzchni. 5) Przy błędach odczytu wykonaj obraz nośnika na inny sprawny dysk, jeśli stan na to pozwala. tests: SMART to wskaźnik, nie gwarancja sprawności. Testy powierzchniowe, benchmark i CHKDSK mogą pogorszyć sytuację niestabilnego nośnika. Przy niezastąpionych danych najpierw konsultacja z odzyskiem danych. repair: Po bezpiecznej kopii: wymień potwierdzony przewód/adapter, popraw montaż lub wymień nośnik. Firmware aktualizuj tylko według instrukcji producenta i przy stabilnym zasilaniu. Nie formatuj, jeśli dane nie są zabezpieczone. verify: Sprawdź ponowne wykrywanie po zimnym starcie, SMART, temperaturę, transfer dużego pliku oraz odczyt kopii. Zweryfikuj kopię przez otwarcie wybranych plików. stop: Przerwij przy klikaniu/stukaniu HDD, zapachu spalenizny, nadmiernym nagrzaniu, znikaniu nośnika podczas odczytu lub danych o dużej wartości.','symptomEn: Drive is not detected, slot fails or detection depends on storage mode. focusEn: M.2 describes form factor; determine whether the slot supports SATA, NVMe or both. causesEn: NAND wear or controller issues; firmware errors; damaged cable/connector; SATA/NVMe incompatibility; overheating; filesystem errors; drive power problems. checksEn: 1) If data matters, minimize tests and writes. 2) Record drive model and symptoms. 3) Check detection in UEFI and OS. 4) Listen for mechanical HDD noises. 5) For a stable drive, copy critical data before testing. stepsEn: 1) Do not repeatedly power a clicking HDD. 2) Inspect cable, port and seating with power disconnected. 3) Read SMART using vendor or trusted tools; no single field is a complete verdict. 4) Separate interface, thermal, firmware and media faults. 5) For read errors, image the drive to another healthy disk if its condition permits. testsEn: SMART is an indicator, not a guarantee. Surface tests, benchmarks and CHKDSK can worsen an unstable drive. For irreplaceable data, consult a recovery specialist first. repairEn: After a safe backup: replace a confirmed cable/adapter, reseat or replace the drive. Update firmware only per vendor instructions and with stable power. Do not format before data is secured. verifyEn: Check detection after cold boot, SMART, temperature, large-file transfer and backup readability. Verify the backup by opening sample files. stopEn: Stop for HDD clicking/knocking, burning smell, overheating, drive disappearing during reads or high-value data.','',''),
('fault:FAULT-30','fault','Bateria i ładowanie','Laptop działa tylko z zasilaczem','Laptop works only with the adapter','symptom: Laptop wyłącza się po odłączeniu adaptera lub bateria nie jest wykrywana. focus: Sprawdź status baterii i adaptera; nie otwieraj ani nie rozbieraj pakietu ogniw. causes: Limit ładowania w oprogramowaniu; niezgodny adapter lub kabel USB-C PD; zużyte ogniwa; błędna komunikacja baterii; gniazdo DC-IN; kontroler ładowania; problem z czujnikiem temperatury. checks: 1) Sprawdź, czy ładowanie nie ma ustawionego limitu (np. ochrona baterii). 2) Użyj zasilacza o zgodnych parametrach. 3) Zapisz status baterii i raport kondycji. 4) Obejrzyj obudowę pod kątem wybrzuszeń. 5) Sprawdź, czy problem występuje po pełnym wyłączeniu i ponownym starcie. steps: 1) Potwierdź model baterii i adaptera. 2) Porównaj status ładowania w systemie i UEFI, jeśli dostępny. 3) Technik ocenia gniazdo, linie identyfikacji i układ ładowania na schemacie. 4) Sprawdza komunikację BMS oraz czujnik temperatury zgodnie z dokumentacją. 5) Nie wykonuje się „naprawy” przez mostkowanie baterii lub bezpieczników. tests: Nie rozbieraj pakietu Li-ion/Li-pol i nie mierz ogniw bez odpowiedniego wyposażenia. Każdy pomiar na płycie musi być zgodny z dokumentacją modelu. Spuchniętej baterii nie testuj ani nie ładuj. repair: Usuń przyczynę: konfiguracja limitu, zgodny adapter/kabel, naprawa gniazda lub obwodu ładowania, wymiana baterii na zatwierdzony numer części. Nie stosuj zamiennika bez zgodności napięcia, BMS i mechaniki. verify: Sprawdź wykrywanie baterii, zmianę poziomu w czasie, ładowanie przy wyłączonym i włączonym urządzeniu, temperaturę i komunikaty systemu. stop: Spuchnięcie, przebicie, wyciek, syczenie, zapach chemiczny lub nadmierne grzanie baterii oznaczają STOP. Nie ściskaj, nie przekłuwaj i nie wrzucaj do zwykłych odpadów.','symptomEn: Laptop turns off when adapter is removed or battery is not detected. focusEn: Check battery and adapter status; never open or dismantle the battery pack. causesEn: Charge threshold in software; incompatible adapter or USB-C PD cable; worn cells; battery communication fault; DC-in jack; charger controller; temperature-sensor issue. checksEn: 1) Check whether charging is limited by a battery-protection feature. 2) Use an adapter with matching specifications. 3) Record battery status and health report. 4) Inspect for swelling. 5) Check after a full shutdown and restart. stepsEn: 1) Confirm battery and adapter models. 2) Compare charging status in OS and UEFI if available. 3) A technician checks jack, identification lines and charger circuit against the schematic. 4) Check BMS communication and temperature sensor per documentation. 5) Never “repair” by bridging battery protection or fuses. testsEn: Do not dismantle a Li-ion/Li-pol pack or probe cells without proper equipment. Board measurements must follow exact model documentation. Never test or charge a swollen battery. repairEn: Correct the cause: charge limit setting, compatible adapter/cable, jack or charging-circuit repair, or battery replacement with approved part number. Do not use a substitute without voltage, BMS and mechanical compatibility. verifyEn: Check battery detection, percentage change over time, charging while off/on, temperature and OS messages. stopEn: Swelling, puncture, leakage, hissing, chemical odor or excessive battery heat mean STOP. Do not squeeze, puncture or place in ordinary waste.','',''),
('fault:FAULT-31','fault','Sterowniki i grafika','Obraz znika po aktualizacji sterownika','Display disappears after a driver update','symptom: Obraz znika po zalogowaniu, po instalacji sterownika lub po aktualizacji systemu. focus: Ustal, czy obraz jest dostępny przed załadowaniem sterownika. causes: Aktualizacja lub sterownik; uszkodzone pliki systemowe; błędny wpis rozruchu; brak miejsca; RAM/nośnik; konflikt oprogramowania; malware; nieprawidłowy tryb UEFI/Secure Boot. checks: 1) Zapisz kod i komunikat. 2) Zabezpiecz dane. 3) Ustal, czy UEFI wykrywa nośnik. 4) Odłącz niepotrzebne akcesoria. 5) Zanotuj ostatnie aktualizacje i zmiany. steps: 1) Oddziel problem sprzętowy od systemowego, sprawdzając POST/UEFI. 2) Sprawdź stan nośnika przed naprawą systemu. 3) Używaj środowiska odzyskiwania producenta/systemu i zachowaj logi. 4) Cofnij tylko konkretną, znaną zmianę (sterownik/aktualizacja), nie wykonuj wielu napraw naraz. 5) Przed reinstalacją potwierdź backup i klucz BitLocker. tests: SFC/DISM/CHKDSK nie zastępują diagnozy nośnika i nie powinny być pierwszym krokiem przy fizycznie uszkodzonym dysku. Zrzuty BSOD i logi są ważniejsze niż sam opis „nie działa”. repair: Naprawiaj przyczynowo: przywróć sterownik/aktualizację, popraw wpis boot, zwolnij miejsce bez usuwania nieznanych plików lub wymień potwierdzony sprzęt. Reinstalacja jest ostatecznością po kopii. verify: Wykonaj kilka restartów, sprawdź dziennik zdarzeń, aktualizacje, urządzenia, kopie danych i odtworzenie punktu przywracania/obrazu, jeśli wymagane. stop: Nie formatuj przy niepewnym stanie danych lub braku klucza BitLocker. Przerwij przy błędach odczytu, znikającym dysku lub podejrzeniu malware szyfrującego pliki.','symptomEn: Display disappears after sign-in, driver installation or OS update. focusEn: Determine whether the display works before the driver loads. causesEn: Update or driver; corrupted system files; invalid boot entry; low storage; RAM/drive fault; software conflict; malware; incorrect UEFI/Secure Boot mode. checksEn: 1) Record code and message. 2) Protect data. 3) Determine whether UEFI detects the drive. 4) Disconnect unnecessary peripherals. 5) Record recent updates and changes. stepsEn: 1) Separate hardware from OS by checking POST/UEFI. 2) Check drive health before OS repair. 3) Use vendor/OS recovery and retain logs. 4) Roll back one known change (driver/update); do not apply many repairs at once. 5) Confirm backup and BitLocker key before reinstalling. testsEn: SFC/DISM/CHKDSK do not replace drive diagnostics and should not be the first step on a physically failing drive. BSOD dumps and logs are more useful than “it does not work”. repairEn: Repair the cause: roll back driver/update, correct boot entry, free space without deleting unknown files or replace confirmed hardware. Reinstall only after backup and as a last resort. verifyEn: Perform several restarts; check Event Viewer, updates, devices, backups and restore-point/image recovery if required. stopEn: Do not format when data status is uncertain or BitLocker key is missing. Stop for read errors, disappearing drive or suspected file-encrypting malware.','',''),
('fault:FAULT-32','fault','Dyski i Windows','Brakuje miejsca na dysku','Disk space is running out','symptom: Mało wolnego miejsca, aktualizacje nie przechodzą lub aplikacje zgłaszają brak miejsca. focus: Zidentyfikuj największe katalogi i typ danych; nie kasuj nieznanych plików systemowych. causes: Aktualizacja lub sterownik; uszkodzone pliki systemowe; błędny wpis rozruchu; brak miejsca; RAM/nośnik; konflikt oprogramowania; malware; nieprawidłowy tryb UEFI/Secure Boot. checks: 1) Zapisz kod i komunikat. 2) Zabezpiecz dane. 3) Ustal, czy UEFI wykrywa nośnik. 4) Odłącz niepotrzebne akcesoria. 5) Zanotuj ostatnie aktualizacje i zmiany. steps: 1) Oddziel problem sprzętowy od systemowego, sprawdzając POST/UEFI. 2) Sprawdź stan nośnika przed naprawą systemu. 3) Używaj środowiska odzyskiwania producenta/systemu i zachowaj logi. 4) Cofnij tylko konkretną, znaną zmianę (sterownik/aktualizacja), nie wykonuj wielu napraw naraz. 5) Przed reinstalacją potwierdź backup i klucz BitLocker. tests: SFC/DISM/CHKDSK nie zastępują diagnozy nośnika i nie powinny być pierwszym krokiem przy fizycznie uszkodzonym dysku. Zrzuty BSOD i logi są ważniejsze niż sam opis „nie działa”. repair: Naprawiaj przyczynowo: przywróć sterownik/aktualizację, popraw wpis boot, zwolnij miejsce bez usuwania nieznanych plików lub wymień potwierdzony sprzęt. Reinstalacja jest ostatecznością po kopii. verify: Wykonaj kilka restartów, sprawdź dziennik zdarzeń, aktualizacje, urządzenia, kopie danych i odtworzenie punktu przywracania/obrazu, jeśli wymagane. stop: Nie formatuj przy niepewnym stanie danych lub braku klucza BitLocker. Przerwij przy błędach odczytu, znikającym dysku lub podejrzeniu malware szyfrującego pliki.','symptomEn: Low free space, failed updates or applications report insufficient storage. focusEn: Identify largest folders and data types; do not delete unknown system files. causesEn: Update or driver; corrupted system files; invalid boot entry; low storage; RAM/drive fault; software conflict; malware; incorrect UEFI/Secure Boot mode. checksEn: 1) Record code and message. 2) Protect data. 3) Determine whether UEFI detects the drive. 4) Disconnect unnecessary peripherals. 5) Record recent updates and changes. stepsEn: 1) Separate hardware from OS by checking POST/UEFI. 2) Check drive health before OS repair. 3) Use vendor/OS recovery and retain logs. 4) Roll back one known change (driver/update); do not apply many repairs at once. 5) Confirm backup and BitLocker key before reinstalling. testsEn: SFC/DISM/CHKDSK do not replace drive diagnostics and should not be the first step on a physically failing drive. BSOD dumps and logs are more useful than “it does not work”. repairEn: Repair the cause: roll back driver/update, correct boot entry, free space without deleting unknown files or replace confirmed hardware. Reinstall only after backup and as a last resort. verifyEn: Perform several restarts; check Event Viewer, updates, devices, backups and restore-point/image recovery if required. stopEn: Do not format when data status is uncertain or BitLocker key is missing. Stop for read errors, disappearing drive or suspected file-encrypting malware.','',''),
('fault:FAULT-33','fault','Porty USB','Urządzenie USB nie jest rozpoznawane','USB device is not recognized','symptom: Komunikat urządzenia, rozłączanie, brak zasilania lub brak urządzenia w systemie. focus: Porównaj urządzenie i kabel na innym komputerze; sprawdź kilka portów. causes: Uszkodzony kabel/akcesorium; ograniczona funkcja danego portu; zabrudzone lub wygięte styki; zabezpieczenie ESD/TVS; bezpiecznik/polyfuse; kontroler USB/PCH; niewłaściwy adapter lub wersja protokołu. checks: 1) Sprawdź inne akcesorium i znany sprawny kabel. 2) Wypróbuj drugi port. 3) Obejrzyj złącze bez wkładania metalowych przedmiotów. 4) Dla wideo sprawdź wejście i źródło monitora. 5) Dla USB-C potwierdź w specyfikacji obsługę danych, ładowania i obrazu oddzielnie. steps: 1) Zapisz urządzenie, kabel, port i dokładny objaw. 2) Sprawdź wykrywanie w systemie i komunikaty. 3) Technik ogląda styki, mocowanie i ochronę ESD. 4) Schemat wskazuje zasilanie portu, kontroler i linie danych. 5) Nie wykonuj pomiarów na pinach przy niepewnym pinoucie. tests: USB-C/HDMI/USB mają różne pinouty i warianty. Nie zakładaj, że kolory przewodów lub pinout z ogólnej planszy pasują do każdego kabla/gniazda. repair: Wymień uszkodzony kabel/adapter; napraw mechaniczne mocowanie złącza; wymień bezpiecznik lub ochronę dopiero po ustaleniu przyczyny. Uszkodzenia linii sygnałowych i kontrolera wymagają naprawy płyty. verify: Sprawdź kilka cykli podłączania, transfer danych lub obraz, stabilność zasilania oraz brak nagrzewania złącza. stop: Przerwij przy wygiętych pinach, iskrzeniu, nadpaleniu, wodzie lub nagrzewaniu kabla/portu.','symptomEn: Device error, disconnects, no power or device missing in OS. focusEn: Compare the device and cable on another computer; test multiple ports. causesEn: Faulty cable/accessory; port feature limitation; dirty or bent contacts; ESD/TVS protection; fuse/polyfuse; USB/PCH controller; incompatible adapter or protocol version. checksEn: 1) Test another accessory and known-good cable. 2) Try another port. 3) Inspect the connector without inserting metal objects. 4) For video, check monitor input/source. 5) For USB-C, verify data, charging and video capabilities separately in the specification. stepsEn: 1) Record device, cable, port and exact symptom. 2) Check OS detection and messages. 3) A technician inspects contacts, mounting and ESD protection. 4) The schematic identifies port power, controller and data lines. 5) Never probe pins with an uncertain pinout. testsEn: USB-C/HDMI/USB have different pinouts and variants. Do not assume wire colors or a generic chart match every cable/connector. repairEn: Replace a faulty cable/adapter; repair mechanical connector mounting; replace fuse/protection only after identifying the cause. Signal-line or controller damage requires board repair. verifyEn: Check multiple connect cycles, data transfer or video, stable power and no connector heating. stopEn: Stop for bent pins, arcing, burning, liquid or cable/port heating.','',''),
('fault:FAULT-34','fault','Zasilanie i Windows','Komputer nie wraca z uśpienia','Computer does not wake from sleep','symptom: Czarny ekran po wybudzeniu, brak reakcji klawiatury albo samoczynne restarty. focus: Sprawdź, czy komputer faktycznie pracuje i czy obraz nie został przełączony na inny ekran. causes: Aktualizacja lub sterownik; uszkodzone pliki systemowe; błędny wpis rozruchu; brak miejsca; RAM/nośnik; konflikt oprogramowania; malware; nieprawidłowy tryb UEFI/Secure Boot. checks: 1) Zapisz kod i komunikat. 2) Zabezpiecz dane. 3) Ustal, czy UEFI wykrywa nośnik. 4) Odłącz niepotrzebne akcesoria. 5) Zanotuj ostatnie aktualizacje i zmiany. steps: 1) Oddziel problem sprzętowy od systemowego, sprawdzając POST/UEFI. 2) Sprawdź stan nośnika przed naprawą systemu. 3) Używaj środowiska odzyskiwania producenta/systemu i zachowaj logi. 4) Cofnij tylko konkretną, znaną zmianę (sterownik/aktualizacja), nie wykonuj wielu napraw naraz. 5) Przed reinstalacją potwierdź backup i klucz BitLocker. tests: SFC/DISM/CHKDSK nie zastępują diagnozy nośnika i nie powinny być pierwszym krokiem przy fizycznie uszkodzonym dysku. Zrzuty BSOD i logi są ważniejsze niż sam opis „nie działa”. repair: Naprawiaj przyczynowo: przywróć sterownik/aktualizację, popraw wpis boot, zwolnij miejsce bez usuwania nieznanych plików lub wymień potwierdzony sprzęt. Reinstalacja jest ostatecznością po kopii. verify: Wykonaj kilka restartów, sprawdź dziennik zdarzeń, aktualizacje, urządzenia, kopie danych i odtworzenie punktu przywracania/obrazu, jeśli wymagane. stop: Nie formatuj przy niepewnym stanie danych lub braku klucza BitLocker. Przerwij przy błędach odczytu, znikającym dysku lub podejrzeniu malware szyfrującego pliki.','symptomEn: Black screen after wake, unresponsive keyboard or unexpected restarts. focusEn: Check whether the computer is running and whether output switched to another display. causesEn: Update or driver; corrupted system files; invalid boot entry; low storage; RAM/drive fault; software conflict; malware; incorrect UEFI/Secure Boot mode. checksEn: 1) Record code and message. 2) Protect data. 3) Determine whether UEFI detects the drive. 4) Disconnect unnecessary peripherals. 5) Record recent updates and changes. stepsEn: 1) Separate hardware from OS by checking POST/UEFI. 2) Check drive health before OS repair. 3) Use vendor/OS recovery and retain logs. 4) Roll back one known change (driver/update); do not apply many repairs at once. 5) Confirm backup and BitLocker key before reinstalling. testsEn: SFC/DISM/CHKDSK do not replace drive diagnostics and should not be the first step on a physically failing drive. BSOD dumps and logs are more useful than “it does not work”. repairEn: Repair the cause: roll back driver/update, correct boot entry, free space without deleting unknown files or replace confirmed hardware. Reinstall only after backup and as a last resort. verifyEn: Perform several restarts; check Event Viewer, updates, devices, backups and restore-point/image recovery if required. stopEn: Do not format when data status is uncertain or BitLocker key is missing. Stop for read errors, disappearing drive or suspected file-encrypting malware.','',''),
('fault:FAULT-35','fault','Łączność bezprzewodowa','Bluetooth nie łączy urządzenia','Bluetooth will not pair','symptom: Urządzenie nie pojawia się, parowanie nie kończy się lub połączenie zrywa się. focus: Sprawdź tryb parowania, baterię akcesorium i czy nie jest połączone z innym sprzętem. causes: Tryb samolotowy lub przełącznik radiowy; router/AP; błędne hasło; sterownik; usługa systemowa; oszczędzanie energii; antena lub karta Wi-Fi; DHCP/DNS/WAN. checks: 1) Sprawdź tryb samolotowy i fizyczny przełącznik. 2) Porównaj telefon w tej samej sieci. 3) Sprawdź laptop w innej sieci. 4) Zapisz komunikat błędu i siłę sygnału. 5) Uruchom ponownie router tylko po zapisaniu jego statusu i upewnieniu się, że nie wykonuje aktualizacji. steps: 1) Ustal, czy problem dotyczy jednej sieci, wszystkich sieci czy samej karty. 2) Sprawdź Menedżer urządzeń i kod urządzenia. 3) Przywróć właściwy sterownik z witryny producenta po zidentyfikowaniu karty. 4) Sprawdź adres IP, bramę i DNS. 5) Jeśli sygnał jest słaby w kilku lokalizacjach, technik sprawdza anteny i przewody. tests: Zapisz wynik ipconfig /all, ping do bramy i rozpoznawanie nazw DNS. Nie wyłączaj zabezpieczeń routera ani zapory jako „testu” na stałe. repair: Popraw ustawienia sieci, hasło, sterownik lub konfigurację routera. Kartę/antenę wymieniaj dopiero po potwierdzeniu sprzętowym i zgodności z platformą. verify: Sprawdź połączenie po restarcie, transfer pliku, roaming, DNS i stabilność przez kilka minut w zwykłym miejscu użytkowania. stop: Przerwij przy uszkodzonym złączu antenowym, śladach cieczy lub konieczności otwarcia zasilacza/routera. Nie resetuj routera do ustawień fabrycznych bez kopii konfiguracji.','symptomEn: Device is missing, pairing fails or connection drops. focusEn: Check pairing mode, accessory battery and whether it is connected elsewhere. causesEn: Airplane mode or radio switch; router/AP; incorrect password; driver; OS service; power saving; antenna or Wi-Fi card; DHCP/DNS/WAN. checksEn: 1) Check airplane mode and physical switch. 2) Compare a phone on the same network. 3) Test the laptop on another network. 4) Record error message and signal strength. 5) Restart the router only after recording its status and confirming it is not updating. stepsEn: 1) Determine whether the problem affects one network, all networks or the adapter itself. 2) Check Device Manager and device code. 3) Install the correct vendor driver after identifying the adapter. 4) Check IP address, gateway and DNS. 5) If signal is weak in multiple locations, a technician inspects antennas and cables. testsEn: Record ipconfig /all, gateway ping and DNS resolution. Do not permanently disable router security or firewall as a “test”. repairEn: Correct network settings, password, driver or router configuration. Replace adapter/antenna only after hardware confirmation and platform compatibility check. verifyEn: Check connection after restart, file transfer, roaming, DNS and stability for several minutes in the normal use location. stopEn: Stop for damaged antenna connector, liquid traces or any need to open a PSU/router. Do not factory-reset a router without configuration backup.','','');
